insert into learning_evidences (id, dba_id, num, texto) select '56cca7e9-ee1c-5e45-8bac-2f0a88f01aec'::uuid, d.id, 1, 'Interpreta y construye diagramas para representar relaciones aditivas y multiplicativas entre cantidades que se presentan en situaciones o fenómenos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 1;
