insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('56cca7e9-ee1c-5e45-8bac-2f0a88f01aec'::uuid, 'multiple_choice', 'Tenías 12 dulces y te comes 5. ¿Cuántos quedan?', '{"options":["7","6","9","11"],"correctIndex":0,"operation":"12 − 5 = ?","visual":{"tipo":"quitar","icono":"🍬","cantidad":12,"seVan":5}}'::jsonb, 1);
