insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('56cca7e9-ee1c-5e45-8bac-2f0a88f01aec'::uuid, 'multiple_choice', '¿Cuántos globos más tiene Ana que Luis?', '{"options":["3","5","7","8"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Ana","valor":7},{"etiqueta":"Luis","valor":4}]},"ayuda":{"pista":"«Cuántos más» se busca restando: mira la diferencia entre las dos barras.","pasos":["Busca en el dibujo la barra de cada uno y cuánto marca.","La pregunta no es cuántos hay en total: es cuánto le sobra al que tiene más.","Réstale al mayor el menor, y eso es lo que los separa."],"ojo":"Si sumas las dos barras te da cuántos hay entre los dos, que es otra pregunta."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('56cca7e9-ee1c-5e45-8bac-2f0a88f01aec'::uuid, 'multiple_choice', '¿Cuántas fichas menos tiene Sara que Jorge?', '{"options":["4","14","5","8"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Jorge","valor":9},{"etiqueta":"Sara","valor":5}]},"ayuda":{"pista":"«Cuántos más» se busca restando: mira la diferencia entre las dos barras.","pasos":["Busca en el dibujo la barra de cada uno y cuánto marca.","La pregunta no es cuántos hay en total: es cuánto le sobra al que tiene más.","Réstale al mayor el menor, y eso es lo que los separa."],"ojo":"Si sumas las dos barras te da cuántos hay entre los dos, que es otra pregunta."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('56cca7e9-ee1c-5e45-8bac-2f0a88f01aec'::uuid, 'multiple_choice', '¿Cuántos puntos más hizo el azul que el verde?', '{"options":["7","8","9","11"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Azul","valor":15},{"etiqueta":"Verde","valor":8}]},"ayuda":{"pista":"«Cuántos más» se busca restando: mira la diferencia entre las dos barras.","pasos":["Busca en el dibujo la barra de cada uno y cuánto marca.","La pregunta no es cuántos hay en total: es cuánto le sobra al que tiene más.","Réstale al mayor el menor, y eso es lo que los separa."],"ojo":"Si sumas las dos barras te da cuántos hay entre los dos, que es otra pregunta."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', 'Reparten 20 fichas entre 4 niños, iguales. ¿Qué haces?', '{"options":["Reparto el total entre los niños","Junto el total con los niños","Le quito los niños al total","Repito el total tantas veces"],"correctIndex":0,"ayuda":{"pista":"Fíjate si algo se junta, se quita, se repite o se parte en pedazos iguales.","pasos":["Juntar dos cantidades es sumar; sacarle a una es restar.","Repetir lo mismo varias veces es multiplicar.","Partir un total en pedazos iguales es repartir."],"ojo":"La palabra «en total» no siempre pide sumar: depende de si algo se repite."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', 'Cada caja lleva 8 huevos y hay 3 cajas. ¿Qué haces?', '{"options":["Repito el contenido de una caja","Reparto el contenido entre las cajas","Le quito las cajas al contenido","Junto el contenido con las cajas"],"correctIndex":0,"ayuda":{"pista":"Fíjate si algo se junta, se quita, se repite o se parte en pedazos iguales.","pasos":["Juntar dos cantidades es sumar; sacarle a una es restar.","Repetir lo mismo varias veces es multiplicar.","Partir un total en pedazos iguales es repartir."],"ojo":"La palabra «en total» no siempre pide sumar: depende de si algo se repite."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', 'Tenías 30 monedas y gastaste 12. ¿Qué haces?', '{"options":["Le quito lo gastado a lo que tenías","Junto lo gastado con lo que tenías","Reparto lo gastado en partes iguales","Repito lo gastado varias veces"],"correctIndex":0,"ayuda":{"pista":"Fíjate si algo se junta, se quita, se repite o se parte en pedazos iguales.","pasos":["Juntar dos cantidades es sumar; sacarle a una es restar.","Repetir lo mismo varias veces es multiplicar.","Partir un total en pedazos iguales es repartir."],"ojo":"La palabra «en total» no siempre pide sumar: depende de si algo se repite."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('56cca7e9-ee1c-5e45-8bac-2f0a88f01aec'::uuid, 'multiple_choice', 'Hay 4 filas con 5 sillas cada una. ¿Qué cuenta da el total?', '{"options":["4 veces 5","4 más 5","5 menos 4","5 entre 4"],"correctIndex":0,"visual":{"tipo":"arreglo","icono":"🪑","filas":4,"columnas":5},"ayuda":{"pista":"No te piden el total: te piden con qué cuenta se saca.","pasos":["Mira qué se repite: hay varias filas y todas tienen lo mismo.","Cuando algo igual se repite varias veces, la cuenta es multiplicar.","El primer número dice cuántas filas hay y el segundo cuántos tiene cada una."],"ojo":"Sumar los dos números no sirve: eso junta una fila con el número de filas."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('56cca7e9-ee1c-5e45-8bac-2f0a88f01aec'::uuid, 'multiple_choice', 'Hay 3 filas con 6 galletas cada una. ¿Qué cuenta da el total?', '{"options":["3 veces 6","3 más 6","6 menos 3","6 entre 3"],"correctIndex":0,"visual":{"tipo":"arreglo","icono":"🍪","filas":3,"columnas":6},"ayuda":{"pista":"No te piden el total: te piden con qué cuenta se saca.","pasos":["Mira qué se repite: hay varias filas y todas tienen lo mismo.","Cuando algo igual se repite varias veces, la cuenta es multiplicar.","El primer número dice cuántas filas hay y el segundo cuántos tiene cada una."],"ojo":"Sumar los dos números no sirve: eso junta una fila con el número de filas."}}'::jsonb, 4);
