insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', '¿En cuál de estas situaciones hay que multiplicar?', '{"options":["6 cajas con 4 lápices cada una","6 lápices y te regalan 4 más","6 lápices y te quitan 4","6 lápices repartidos entre 4 niños"],"correctIndex":0,"ayuda":{"pista":"Busca la que tenga varios montones y todos del mismo tamaño.","pasos":["Se multiplica cuando algo igual se repite: montones del mismo tamaño.","Si a una cantidad le llega más, se suma; si se le va, se resta.","Si un total se parte en pedazos iguales, se reparte."],"ojo":"Que haya dos números no quiere decir que haya que multiplicarlos."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', '¿En cuál de estas situaciones hay que multiplicar?', '{"options":["5 mesas con 3 puestos cada una","5 puestos y ponen 3 más","5 puestos y quitan 3","5 puestos repartidos entre 3 grupos"],"correctIndex":0,"ayuda":{"pista":"Busca la que tenga varios montones y todos del mismo tamaño.","pasos":["Se multiplica cuando algo igual se repite: montones del mismo tamaño.","Si a una cantidad le llega más, se suma; si se le va, se resta.","Si un total se parte en pedazos iguales, se reparte."],"ojo":"Que haya dos números no quiere decir que haya que multiplicarlos."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', '¿En cuál de estas situaciones hay que multiplicar?', '{"options":["7 bolsas con 2 galletas cada una","7 galletas y te dan 2 más","7 galletas y te comes 2","7 galletas repartidas entre 2 niños"],"correctIndex":0,"ayuda":{"pista":"Busca la que tenga varios montones y todos del mismo tamaño.","pasos":["Se multiplica cuando algo igual se repite: montones del mismo tamaño.","Si a una cantidad le llega más, se suma; si se le va, se resta.","Si un total se parte en pedazos iguales, se reparte."],"ojo":"Que haya dos números no quiere decir que haya que multiplicarlos."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', 'Sabes que cada hora vale $2.000. ¿Qué NO puedes calcular?', '{"options":["Cuántas horas jugó Camilo","Cuánto cuestan cuatro horas","Cuánto cuestan dos horas","Cuánto cuesta media hora menos"],"correctIndex":0,"ayuda":{"pista":"Revisa qué datos te dieron y cuáles harían falta para cada pregunta.","pasos":["Anota qué sabes exactamente. Nada más que eso.","Lee cada pregunta y busca si el dato que necesita está ahí.","La que pide un dato que nadie te dio es la que no se puede responder."],"ojo":"Saber que algo no se puede calcular también es saber matemáticas."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', 'Sabes que hay 24 niños y 4 mesas iguales. ¿Qué NO sabes?', '{"options":["Cuántos años tiene cada niño","Cuántos niños hay por mesa","Cuántos niños hay en dos mesas","Cuántas mesas se usaron"],"correctIndex":0,"ayuda":{"pista":"Revisa qué datos te dieron y cuáles harían falta para cada pregunta.","pasos":["Anota qué sabes exactamente. Nada más que eso.","Lee cada pregunta y busca si el dato que necesita está ahí.","La que pide un dato que nadie te dio es la que no se puede responder."],"ojo":"Saber que algo no se puede calcular también es saber matemáticas."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a27d9ec5-cb20-5f0d-879c-4c57bb679278'::uuid, 'multiple_choice', 'Sabes que la cinta mide 60 cm y la cortas por la mitad.', '{"options":["No se sabe de qué color es","No se sabe cuánto mide cada parte","No se sabe cuántas partes quedan","No se sabe cuánto medía antes"],"correctIndex":0,"ayuda":{"pista":"Revisa qué datos te dieron y cuáles harían falta para cada pregunta.","pasos":["Anota qué sabes exactamente. Nada más que eso.","Lee cada pregunta y busca si el dato que necesita está ahí.","La que pide un dato que nadie te dio es la que no se puede responder."],"ojo":"Saber que algo no se puede calcular también es saber matemáticas."}}'::jsonb, 10);
