insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'El dibujo muestra los votos. ¿Cuál sabor ganó?', '{"options":["Ganó la mora","Ganó la fresa","Ganó la uva","Quedaron empatados"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fresa","valor":12},{"etiqueta":"Mora","valor":18},{"etiqueta":"Uva","valor":9}]},"ayuda":{"pista":"Ganó el de la barra más larga, no el que esté escrito primero.","pasos":["Mira las barras y compara cuál llega más lejos.","Si dos llegan igual de lejos, entonces nadie ganó: quedaron empatados.","Responde con el nombre de esa barra, no con su número."],"ojo":"El orden en que están escritos no dice nada: lo que manda es el largo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'El dibujo muestra los votos. ¿Cuál deporte ganó?', '{"options":["Ganó el fútbol","Ganó el patinaje","Ganó el tenis","Quedaron empatados"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fútbol","valor":14},{"etiqueta":"Patinaje","valor":11},{"etiqueta":"Tenis","valor":7}]},"ayuda":{"pista":"Ganó el de la barra más larga, no el que esté escrito primero.","pasos":["Mira las barras y compara cuál llega más lejos.","Si dos llegan igual de lejos, entonces nadie ganó: quedaron empatados.","Responde con el nombre de esa barra, no con su número."],"ojo":"El orden en que están escritos no dice nada: lo que manda es el largo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'El dibujo muestra los votos. ¿Cuál color ganó?', '{"options":["Quedaron empatados","Ganó el rojo","Ganó el azul","Ganó el verde"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":10},{"etiqueta":"Azul","valor":10},{"etiqueta":"Verde","valor":6}]},"ayuda":{"pista":"Ganó el de la barra más larga, no el que esté escrito primero.","pasos":["Mira las barras y compara cuál llega más lejos.","Si dos llegan igual de lejos, entonces nadie ganó: quedaron empatados.","Responde con el nombre de esa barra, no con su número."],"ojo":"El orden en que están escritos no dice nada: lo que manda es el largo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cuántos votos hay en total?', '{"options":["17","18","19","21"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fresa","valor":5},{"etiqueta":"Mora","valor":8},{"etiqueta":"Uva","valor":4}]},"ayuda":{"pista":"«En total» es juntarlos todos: suma lo que marca cada barra.","pasos":["Lee el número de cada barra, una por una.","Súmalos de a dos: los dos primeros, y a ese resultado el que sigue.","No dejes ninguna barra por fuera, ni siquiera la más pequeñita."],"ojo":"El total no es el de la barra más larga: es el de todas juntas."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cuántos votos hay en total?', '{"options":["16","17","18","20"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":6},{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":3}]},"ayuda":{"pista":"«En total» es juntarlos todos: suma lo que marca cada barra.","pasos":["Lee el número de cada barra, una por una.","Súmalos de a dos: los dos primeros, y a ese resultado el que sigue.","No dejes ninguna barra por fuera, ni siquiera la más pequeñita."],"ojo":"El total no es el de la barra más larga: es el de todas juntas."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cuántos votos hay en total?', '{"options":["19","9","20","21"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":9},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":5}]},"ayuda":{"pista":"«En total» es juntarlos todos: suma lo que marca cada barra.","pasos":["Lee el número de cada barra, una por una.","Súmalos de a dos: los dos primeros, y a ese resultado el que sigue.","No dejes ninguna barra por fuera, ni siquiera la más pequeñita."],"ojo":"El total no es el de la barra más larga: es el de todas juntas."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b1b46fb8-29d4-5033-8669-1e939ddb9300'::uuid, 'multiple_choice', 'Sin hacer la cuenta, ¿cerca de cuánto da 48 + 31?', '{"options":["80","70","90","100"],"correctIndex":0,"ayuda":{"pista":"Estimar es redondear cada número a la decena más cercana y sumar esas decenas.","pasos":["Mira cada número y busca a qué decena está más cerca.","Por ejemplo, 48 está más cerca de 50 que de 40.","Suma las dos decenas redondas: eso te dice por dónde va el resultado."],"ojo":"Estimar no es equivocarse: es saber por dónde va antes de hacer la cuenta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b1b46fb8-29d4-5033-8669-1e939ddb9300'::uuid, 'multiple_choice', 'Sin hacer la cuenta, ¿cerca de cuánto da 61 + 28?', '{"options":["90","80","100","70"],"correctIndex":0,"ayuda":{"pista":"Estimar es redondear cada número a la decena más cercana y sumar esas decenas.","pasos":["Mira cada número y busca a qué decena está más cerca.","Por ejemplo, 48 está más cerca de 50 que de 40.","Suma las dos decenas redondas: eso te dice por dónde va el resultado."],"ojo":"Estimar no es equivocarse: es saber por dónde va antes de hacer la cuenta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b1b46fb8-29d4-5033-8669-1e939ddb9300'::uuid, 'multiple_choice', 'Sin hacer la cuenta, ¿cerca de cuánto da 34 + 27?', '{"options":["60","50","70","80"],"correctIndex":0,"ayuda":{"pista":"Estimar es redondear cada número a la decena más cercana y sumar esas decenas.","pasos":["Mira cada número y busca a qué decena está más cerca.","Por ejemplo, 48 está más cerca de 50 que de 40.","Suma las dos decenas redondas: eso te dice por dónde va el resultado."],"ojo":"Estimar no es equivocarse: es saber por dónde va antes de hacer la cuenta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', '¿Cuántos votos más tiene la mora que la fresa?', '{"options":["7","27","8","10"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fresa","valor":6},{"etiqueta":"Mora","valor":13},{"etiqueta":"Uva","valor":4}]},"ayuda":{"pista":"«Cuántos más» es una resta entre dos barras, no una suma de todas.","pasos":["Busca solo las dos barras que nombra la pregunta.","Mira cuánto marca cada una.","Réstale a la mayor la menor: eso es lo que las separa."],"ojo":"Aquí sobra una barra. No todos los datos de un gráfico sirven para toda pregunta."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', '¿Cuántos votos menos tiene el pez que el perro?', '{"options":["9","19","6","10"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":14},{"etiqueta":"Gato","valor":8},{"etiqueta":"Pez","valor":5}]},"ayuda":{"pista":"«Cuántos más» es una resta entre dos barras, no una suma de todas.","pasos":["Busca solo las dos barras que nombra la pregunta.","Mira cuánto marca cada una.","Réstale a la mayor la menor: eso es lo que las separa."],"ojo":"Aquí sobra una barra. No todos los datos de un gráfico sirven para toda pregunta."}}'::jsonb, 4);
