insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'Hay 3 filas de 5 frutas. Si pones una fila más, ¿cuántas son?', '{"options":["20","15","21","9"],"correctIndex":0,"visual":{"tipo":"arreglo","icono":"🍎","filas":3,"columnas":5},"ayuda":{"pista":"El dibujo enseña las filas que hay; la pregunta pide una más.","pasos":["Mira cuántos hay en UNA fila: todas tienen lo mismo.","Cuenta las filas del dibujo y súmale la que te piden poner.","Multiplica lo de una fila por ese total de filas."],"ojo":"Contar lo que está dibujado deja la cuenta corta: falta la fila nueva."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'Hay 2 filas de 6 fichas. Si pones una fila más, ¿cuántas son?', '{"options":["18","12","6","9"],"correctIndex":0,"visual":{"tipo":"arreglo","icono":"🔵","filas":2,"columnas":6},"ayuda":{"pista":"El dibujo enseña las filas que hay; la pregunta pide una más.","pasos":["Mira cuántos hay en UNA fila: todas tienen lo mismo.","Cuenta las filas del dibujo y súmale la que te piden poner.","Multiplica lo de una fila por ese total de filas."],"ojo":"Contar lo que está dibujado deja la cuenta corta: falta la fila nueva."}}'::jsonb, 6);
