insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'Un dibujo vale 5 votos. ¿Cuántos votos sacó Ana?', '{"options":["15","10","25","16"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":15},{"etiqueta":"Beto","valor":25},{"etiqueta":"Caro","valor":10}]},"ayuda":{"pista":"Cada dibujito vale varios: cuenta los dibujos y después aplica lo que vale cada uno.","pasos":["Mira debajo del gráfico: ahí dice cuánto vale un dibujo.","Cuenta cuántos dibujos tiene la fila que te preguntan.","Suma ese valor tantas veces como dibujos haya."],"ojo":"El error más común es responder cuántos DIBUJOS hay en vez de cuánto valen."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('05185630-d163-5e1b-8703-934d87b492a4'::uuid, 'multiple_choice', 'Un dibujo vale 10 libros. ¿Cuántos libros hay de cuentos?', '{"options":["30","20","10","13"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"📗","escala":10,"unidad":"libros","datos":[{"etiqueta":"Cuentos","valor":30},{"etiqueta":"Poesía","valor":20},{"etiqueta":"Ciencia","valor":40}]},"ayuda":{"pista":"Cada dibujito vale varios: cuenta los dibujos y después aplica lo que vale cada uno.","pasos":["Mira debajo del gráfico: ahí dice cuánto vale un dibujo.","Cuenta cuántos dibujos tiene la fila que te preguntan.","Suma ese valor tantas veces como dibujos haya."],"ojo":"El error más común es responder cuántos DIBUJOS hay en vez de cuánto valen."}}'::jsonb, 8);
