insert into learning_evidences (id, dba_id, num, texto) select '1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, d.id, 1, 'Compara y ordena números de menor a mayor y viceversa a través de recursos como la calculadora, aplicación, material gráfico que represente billetes, diagramas de colecciones, etc.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 3;
insert into learning_evidences (id, dba_id, num, texto) select 'b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, d.id, 2, 'Propone ejemplos y comunica de forma oral y escrita las condiciones que puede establecer para conservar una relación (mayor que, menor que) cuando se aplican algunas operaciones a ellos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 3;
insert into learning_evidences (id, dba_id, num, texto) select '9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, d.id, 3, 'Reconoce y establece relaciones entre expresiones numéricas (hay más, hay menos, hay la misma cantidad) y describe el tipo de operaciones que debe realizarse para que a pesar de cambiar los valores numéricos, la relación se conserve.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 3;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál de estos números es el MAYOR?', '{"options":["374","347","337","343"],"correctIndex":0,"ayuda":{"pista":"Compara primero la cifra de más a la izquierda; solo si empatan, pasa a la siguiente.","pasos":["Mira la primera cifra de cada número, la de más a la izquierda.","El que la tenga más grande ya ganó, sin mirar nada más.","Si varias empatan ahí, compara la cifra que sigue, y así."],"ojo":"Lee bien si te piden el MAYOR o el MENOR: es la trampa más común."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál de estos números es el MENOR?', '{"options":["419","491","441","494"],"correctIndex":0,"ayuda":{"pista":"Compara primero la cifra de más a la izquierda; solo si empatan, pasa a la siguiente.","pasos":["Mira la primera cifra de cada número, la de más a la izquierda.","El que la tenga más grande ya ganó, sin mirar nada más.","Si varias empatan ahí, compara la cifra que sigue, y así."],"ojo":"Lee bien si te piden el MAYOR o el MENOR: es la trampa más común."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál de estos números es el MAYOR?', '{"options":["620","602","612","608"],"correctIndex":0,"ayuda":{"pista":"Compara primero la cifra de más a la izquierda; solo si empatan, pasa a la siguiente.","pasos":["Mira la primera cifra de cada número, la de más a la izquierda.","El que la tenga más grande ya ganó, sin mirar nada más.","Si varias empatan ahí, compara la cifra que sigue, y así."],"ojo":"Lee bien si te piden el MAYOR o el MENOR: es la trampa más común."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'En un plato hay 7 uvas y en otro 7. ¿Cómo están?', '{"options":["Hay la misma cantidad","Hay más en el primero","Hay más en el segundo","No alcanza el dato"],"correctIndex":0,"ayuda":{"pista":"Compara las dos cantidades; si a una no le pusieron número, no se puede decidir.","pasos":["Mira si te dieron un número para cada plato.","Si los dos tienen número, compáralos y ya.","Si uno dice solo «varias» o «algunas», no hay con qué compararlo."],"ojo":"«Varias» no es un número: puede ser más o puede ser menos, y por eso no alcanza."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'En un plato hay 12 uvas y en otro 8. ¿Cómo están?', '{"options":["Hay más en el primero","Hay la misma cantidad","Hay más en el segundo","No alcanza el dato"],"correctIndex":0,"ayuda":{"pista":"Compara las dos cantidades; si a una no le pusieron número, no se puede decidir.","pasos":["Mira si te dieron un número para cada plato.","Si los dos tienen número, compáralos y ya.","Si uno dice solo «varias» o «algunas», no hay con qué compararlo."],"ojo":"«Varias» no es un número: puede ser más o puede ser menos, y por eso no alcanza."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'En un plato hay 6 uvas y en otro «varias». ¿Cómo están?', '{"options":["No alcanza el dato","Hay la misma cantidad","Hay más en el primero","Hay más en el segundo"],"correctIndex":0,"ayuda":{"pista":"Compara las dos cantidades; si a una no le pusieron número, no se puede decidir.","pasos":["Mira si te dieron un número para cada plato.","Si los dos tienen número, compáralos y ya.","Si uno dice solo «varias» o «algunas», no hay con qué compararlo."],"ojo":"«Varias» no es un número: puede ser más o puede ser menos, y por eso no alcanza."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál número está entre 250 y 300?', '{"options":["274","250","305","247"],"correctIndex":0,"ayuda":{"pista":"Estar «entre» es cumplir dos cosas a la vez: pasar del primero y no llegar al segundo.","pasos":["Descarta los que sean más pequeños que el primero.","Descarta los que sean más grandes que el segundo.","El que sobrevive a las dos pruebas es el que está entre los dos."],"ojo":"Cumplir una sola de las dos condiciones no alcanza: tienen que ser las dos."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál número está entre 400 y 450?', '{"options":["418","400","462","395"],"correctIndex":0,"ayuda":{"pista":"Estar «entre» es cumplir dos cosas a la vez: pasar del primero y no llegar al segundo.","pasos":["Descarta los que sean más pequeños que el primero.","Descarta los que sean más grandes que el segundo.","El que sobrevive a las dos pruebas es el que está entre los dos."],"ojo":"Cumplir una sola de las dos condiciones no alcanza: tienen que ser las dos."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál número está entre 700 y 800?', '{"options":["765","700","815","697"],"correctIndex":0,"ayuda":{"pista":"Estar «entre» es cumplir dos cosas a la vez: pasar del primero y no llegar al segundo.","pasos":["Descarta los que sean más pequeños que el primero.","Descarta los que sean más grandes que el segundo.","El que sobrevive a las dos pruebas es el que está entre los dos."],"ojo":"Cumplir una sola de las dos condiciones no alcanza: tienen que ser las dos."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál número va justo ANTES del 700?', '{"options":["699","701","690","600"],"correctIndex":0,"ayuda":{"pista":"El de antes es uno menos; el de después, uno más.","pasos":["Fíjate si te piden el de antes o el de después.","El anterior se consigue quitando 1, y el siguiente sumando 1.","Cuando el número termina en ceros, al quitar 1 cambian varias cifras a la vez."],"ojo":"El anterior no es el número redondo de más abajo: entre esos dos hay muchos."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál número va justo DESPUÉS del 899?', '{"options":["900","898","809","890"],"correctIndex":0,"ayuda":{"pista":"El de antes es uno menos; el de después, uno más.","pasos":["Fíjate si te piden el de antes o el de después.","El anterior se consigue quitando 1, y el siguiente sumando 1.","Cuando el número termina en ceros, al quitar 1 cambian varias cifras a la vez."],"ojo":"El anterior no es el número redondo de más abajo: entre esos dos hay muchos."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál número va justo ANTES del 510?', '{"options":["509","511","500","501"],"correctIndex":0,"ayuda":{"pista":"El de antes es uno menos; el de después, uno más.","pasos":["Fíjate si te piden el de antes o el de después.","El anterior se consigue quitando 1, y el siguiente sumando 1.","Cuando el número termina en ceros, al quitar 1 cambian varias cifras a la vez."],"ojo":"El anterior no es el número redondo de más abajo: entre esos dos hay muchos."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál lista está ordenada de MENOR a mayor?', '{"options":["125, 152, 215, 251","152, 125, 251, 215","251, 215, 152, 125","215, 251, 125, 152"],"correctIndex":0,"ayuda":{"pista":"Recorre cada lista de izquierda a derecha y comprueba que siempre vaya para el mismo lado.","pasos":["Toma la primera lista y compara el primero con el segundo.","Si va bien, sigue con el segundo y el tercero, y así hasta el final.","Con que un solo par esté al revés, esa lista ya no sirve."],"ojo":"No basta con mirar el primero y el último: hay que revisar todos los pasos."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál lista está ordenada de MAYOR a menor?', '{"options":["480, 408, 84, 48","48, 84, 408, 480","408, 480, 48, 84","84, 48, 480, 408"],"correctIndex":0,"ayuda":{"pista":"Recorre cada lista de izquierda a derecha y comprueba que siempre vaya para el mismo lado.","pasos":["Toma la primera lista y compara el primero con el segundo.","Si va bien, sigue con el segundo y el tercero, y así hasta el final.","Con que un solo par esté al revés, esa lista ya no sirve."],"ojo":"No basta con mirar el primero y el último: hay que revisar todos los pasos."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1695dd38-c912-5077-8f26-66905cfb2e46'::uuid, 'multiple_choice', '¿Cuál lista está ordenada de MENOR a mayor?', '{"options":["309, 390, 903, 930","390, 309, 930, 903","930, 903, 390, 309","903, 930, 309, 390"],"correctIndex":0,"ayuda":{"pista":"Recorre cada lista de izquierda a derecha y comprueba que siempre vaya para el mismo lado.","pasos":["Toma la primera lista y compara el primero con el segundo.","Si va bien, sigue con el segundo y el tercero, y así hasta el final.","Con que un solo par esté al revés, esa lista ya no sirve."],"ojo":"No basta con mirar el primero y el último: hay que revisar todos los pasos."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Tienes 9 y yo 6. Los dos ganamos 4. ¿Quién tiene más?', '{"options":["Tú, igual que antes","Yo, porque gané lo mismo","Quedamos con la misma","Ya no se puede saber"],"correctIndex":0,"ayuda":{"pista":"Si a los dos les pasa lo MISMO, la diferencia no cambia; si solo a uno, hay que mirar otra vez.","pasos":["Mira quién tenía más antes de que pasara nada.","Si los dos ganan o pierden lo mismo, el que iba adelante sigue adelante.","Si solo uno cambia, compara de nuevo con los números nuevos."],"ojo":"Darles a los dos no empata a nadie: los sube a los dos por igual."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Tienes 9 y yo 6. Solo yo gano 5. ¿Quién tiene más?', '{"options":["Yo, porque cambié el orden","Tú, igual que antes","Quedamos con la misma","Ya no se puede saber"],"correctIndex":0,"ayuda":{"pista":"Si a los dos les pasa lo MISMO, la diferencia no cambia; si solo a uno, hay que mirar otra vez.","pasos":["Mira quién tenía más antes de que pasara nada.","Si los dos ganan o pierden lo mismo, el que iba adelante sigue adelante.","Si solo uno cambia, compara de nuevo con los números nuevos."],"ojo":"Darles a los dos no empata a nadie: los sube a los dos por igual."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Tienes 9 y yo 6. Yo gano 3. ¿Quién tiene más?', '{"options":["Quedamos con la misma","Tú, igual que antes","Yo, porque cambié el orden","Ya no se puede saber"],"correctIndex":0,"ayuda":{"pista":"Si a los dos les pasa lo MISMO, la diferencia no cambia; si solo a uno, hay que mirar otra vez.","pasos":["Mira quién tenía más antes de que pasara nada.","Si los dos ganan o pierden lo mismo, el que iba adelante sigue adelante.","Si solo uno cambia, compara de nuevo con los números nuevos."],"ojo":"Darles a los dos no empata a nadie: los sube a los dos por igual."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'Ana tiene 10 y Beto 14. ¿Qué haces para dejarlos iguales?', '{"options":["Le doy 4 a Ana","Le doy 4 a Beto","Les doy 4 a los dos","Le quito 4 a Ana"],"correctIndex":0,"ayuda":{"pista":"Primero mira cuánto los separa: eso es lo que hay que mover.","pasos":["Resta el menor del mayor: eso es lo que los separa.","Puedes darle esa diferencia al que tiene menos, o quitársela al que tiene más.","Si le das a los dos lo mismo, siguen igual de separados que antes."],"ojo":"Darles a los dos la misma cantidad no los empata nunca."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'Ana tiene 15 y Beto 9. ¿Qué haces para dejarlos iguales?', '{"options":["Le quito 6 a Ana","Le quito 6 a Beto","Les quito 6 a los dos","Le doy 6 a Ana"],"correctIndex":0,"ayuda":{"pista":"Primero mira cuánto los separa: eso es lo que hay que mover.","pasos":["Resta el menor del mayor: eso es lo que los separa.","Puedes darle esa diferencia al que tiene menos, o quitársela al que tiene más.","Si le das a los dos lo mismo, siguen igual de separados que antes."],"ojo":"Darles a los dos la misma cantidad no los empata nunca."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'Ana tiene 13 y Beto 8. ¿Qué haces para dejarlos iguales?', '{"options":["Le doy 5 a Beto","Le quito 5 a Beto","Le doy 5 a Ana y 5 a Beto","Le quito 5 a Ana"],"correctIndex":0,"ayuda":{"pista":"Primero mira cuánto los separa: eso es lo que hay que mover.","pasos":["Resta el menor del mayor: eso es lo que los separa.","Puedes darle esa diferencia al que tiene menos, o quitársela al que tiene más.","Si le das a los dos lo mismo, siguen igual de separados que antes."],"ojo":"Darles a los dos la misma cantidad no los empata nunca."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Antonio tiene más que Bea. A los dos les quitan 2.', '{"options":["Antonio sigue teniendo más","Antonio y Bea quedan iguales","Bea le pasa a Antonio","Depende de cuánto tenía cada uno"],"correctIndex":0,"ayuda":{"pista":"Quitarles lo mismo a los dos deja la diferencia intacta.","pasos":["Imagina la diferencia como el pedazo que le sobra al que tiene más.","Si a los dos les quitas lo mismo, ese pedazo sigue siendo igual de grande.","Por eso el que tenía más sigue teniendo más."],"ojo":"Si solo a uno le quitan, puede cambiar todo, y a veces no se sabe sin los números."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Antonio tiene más que Bea. A Antonio le quitan 6.', '{"options":["Depende de cuánto tenía cada uno","Antonio sigue teniendo más","Antonio y Bea quedan iguales","Bea le pasa a Antonio seguro"],"correctIndex":0,"ayuda":{"pista":"Quitarles lo mismo a los dos deja la diferencia intacta.","pasos":["Imagina la diferencia como el pedazo que le sobra al que tiene más.","Si a los dos les quitas lo mismo, ese pedazo sigue siendo igual de grande.","Por eso el que tenía más sigue teniendo más."],"ojo":"Si solo a uno le quitan, puede cambiar todo, y a veces no se sabe sin los números."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Antonio y Bea tienen igual. A los dos les dan 7.', '{"options":["Antonio y Bea siguen iguales","Antonio queda con más","Bea queda con más que Antonio","Depende de cuánto tenía cada uno"],"correctIndex":0,"ayuda":{"pista":"Quitarles lo mismo a los dos deja la diferencia intacta.","pasos":["Imagina la diferencia como el pedazo que le sobra al que tiene más.","Si a los dos les quitas lo mismo, ese pedazo sigue siendo igual de grande.","Por eso el que tenía más sigue teniendo más."],"ojo":"Si solo a uno le quitan, puede cambiar todo, y a veces no se sabe sin los números."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'Hay 8 y 8. ¿Qué operación deja el primero con más?', '{"options":["Sumarle 3 al primero","Sumarle 3 a los dos","Quitarle 3 al primero","Quitarle 3 a los dos"],"correctIndex":0,"ayuda":{"pista":"Lo que se le hace a UNO solo cambia la comparación; lo que se le hace a los dos, no.","pasos":["Parten iguales, así que cualquier cambio en los dos los deja iguales.","Para que uno quede con más, hay que subirle a ese o bajarle al otro.","Decide a cuál de los dos le conviene el cambio según lo que te preguntan."],"ojo":"Quitarle al segundo deja al primero con más, aunque al primero no le hayas tocado nada."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'Hay 8 y 8. ¿Qué operación los deja como estaban?', '{"options":["Sumarle 3 a los dos","Sumarle 3 al primero","Quitarle 3 al primero","Sumarle 3 solo al segundo"],"correctIndex":0,"ayuda":{"pista":"Lo que se le hace a UNO solo cambia la comparación; lo que se le hace a los dos, no.","pasos":["Parten iguales, así que cualquier cambio en los dos los deja iguales.","Para que uno quede con más, hay que subirle a ese o bajarle al otro.","Decide a cuál de los dos le conviene el cambio según lo que te preguntan."],"ojo":"Quitarle al segundo deja al primero con más, aunque al primero no le hayas tocado nada."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b4b1b93-3780-5a76-8d94-15979baa8cd3'::uuid, 'multiple_choice', 'Hay 8 y 8. ¿Qué operación deja el segundo con más?', '{"options":["Quitarle 3 al primero","Quitarle 3 a los dos","Sumarle 3 al primero","Sumarle 3 a los dos"],"correctIndex":0,"ayuda":{"pista":"Lo que se le hace a UNO solo cambia la comparación; lo que se le hace a los dos, no.","pasos":["Parten iguales, así que cualquier cambio en los dos los deja iguales.","Para que uno quede con más, hay que subirle a ese o bajarle al otro.","Decide a cuál de los dos le conviene el cambio según lo que te preguntan."],"ojo":"Quitarle al segundo deja al primero con más, aunque al primero no le hayas tocado nada."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Un número en el espacio: 3 + ? es mayor que 8. ¿Cuántos sirven?', '{"options":["Muchos, del 6 en adelante","Solo uno, el 6","Solo dos, el 5 y el 6","Ninguno sirve"],"correctIndex":0,"ayuda":{"pista":"Prueba con un número, mira si cumple, y después mira si los vecinos también cumplen.","pasos":["Empieza probando un número cualquiera y comprueba la condición.","Si el que probaste sirve, mira qué pasa con el que sigue y con el anterior.","Cuando la condición dice «mayor que» suelen servir muchos; cuando dice «igual a», uno solo."],"ojo":"La pregunta no es cuál número sirve, sino CUÁNTOS sirven. No es lo mismo."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Un número en el espacio: 4 + ? es igual a 9. ¿Cuántos sirven?', '{"options":["Solo uno, el 5","Muchos, del 5 en adelante","Solo dos, el 4 y el 5","Ninguno sirve"],"correctIndex":0,"ayuda":{"pista":"Prueba con un número, mira si cumple, y después mira si los vecinos también cumplen.","pasos":["Empieza probando un número cualquiera y comprueba la condición.","Si el que probaste sirve, mira qué pasa con el que sigue y con el anterior.","Cuando la condición dice «mayor que» suelen servir muchos; cuando dice «igual a», uno solo."],"ojo":"La pregunta no es cuál número sirve, sino CUÁNTOS sirven. No es lo mismo."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b4984999-9716-552d-8df9-2ae3d5e75b3a'::uuid, 'multiple_choice', 'Un número en el espacio: 2 + ? es menor que 5. ¿Cuántos sirven?', '{"options":["Solo tres: 0, 1 y 2","Solo uno, el 2","Muchos, del 2 en adelante","Ninguno sirve"],"correctIndex":0,"ayuda":{"pista":"Prueba con un número, mira si cumple, y después mira si los vecinos también cumplen.","pasos":["Empieza probando un número cualquiera y comprueba la condición.","Si el que probaste sirve, mira qué pasa con el que sigue y con el anterior.","Cuando la condición dice «mayor que» suelen servir muchos; cuando dice «igual a», uno solo."],"ojo":"La pregunta no es cuál número sirve, sino CUÁNTOS sirven. No es lo mismo."}}'::jsonb, 10);
