insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', '¿Con cuál de estos averiguas lo que PESA una papaya?', '{"options":["Con una balanza","Con una regla","Con un reloj","Con una jarra marcada"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una cosa distinta: piensa qué te están preguntando.","pasos":["Lo que pesa se averigua con algo que compare pesos.","Lo que mide de largo, con algo que tenga marcas de longitud.","Lo que dura, con algo que cuente el tiempo."],"ojo":"El instrumento no se escoge por el objeto sino por lo que le quieres averiguar."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', '¿Con cuál de estos averiguas lo que MIDE una mesa?', '{"options":["Con un metro","Con una balanza","Con un reloj","Con una jarra marcada"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una cosa distinta: piensa qué te están preguntando.","pasos":["Lo que pesa se averigua con algo que compare pesos.","Lo que mide de largo, con algo que tenga marcas de longitud.","Lo que dura, con algo que cuente el tiempo."],"ojo":"El instrumento no se escoge por el objeto sino por lo que le quieres averiguar."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', '¿Con cuál de estos averiguas lo que DURA una canción?', '{"options":["Con un reloj","Con una balanza","Con una regla","Con una jarra marcada"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una cosa distinta: piensa qué te están preguntando.","pasos":["Lo que pesa se averigua con algo que compare pesos.","Lo que mide de largo, con algo que tenga marcas de longitud.","Lo que dura, con algo que cuente el tiempo."],"ojo":"El instrumento no se escoge por el objeto sino por lo que le quieres averiguar."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', 'Quieres saber cuánta agua le cabe a una olla. ¿Qué usas?', '{"options":["Una jarra marcada","Una cuerda larga","Una balanza de cocina","Un calendario"],"correctIndex":0,"ayuda":{"pista":"Lo que cabe adentro se averigua llenándolo con una medida conocida.","pasos":["Piensa qué estás midiendo: si es lo de adentro, necesitas algo que llene.","Un recipiente con marcas te dice cuánto va cabiendo.","Una regla no sirve para eso: mide bordes, no contenido."],"ojo":"Un recipiente alto no siempre es el que más le cabe: también cuenta lo ancho."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', 'Quieres saber cuánto le falta al recreo. ¿Qué usas?', '{"options":["Un reloj de pared","Una cuerda larga","Una balanza de cocina","Una jarra marcada"],"correctIndex":0,"ayuda":{"pista":"Lo que cabe adentro se averigua llenándolo con una medida conocida.","pasos":["Piensa qué estás midiendo: si es lo de adentro, necesitas algo que llene.","Un recipiente con marcas te dice cuánto va cabiendo.","Una regla no sirve para eso: mide bordes, no contenido."],"ojo":"Un recipiente alto no siempre es el que más le cabe: también cuenta lo ancho."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', 'Quieres saber si la maleta va muy cargada. ¿Qué usas?', '{"options":["Una balanza de pie","Una cuerda larga","Un calendario grande","Una jarra marcada"],"correctIndex":0,"ayuda":{"pista":"Lo que cabe adentro se averigua llenándolo con una medida conocida.","pasos":["Piensa qué estás midiendo: si es lo de adentro, necesitas algo que llene.","Un recipiente con marcas te dice cuánto va cabiendo.","Una regla no sirve para eso: mide bordes, no contenido."],"ojo":"Un recipiente alto no siempre es el que más le cabe: también cuenta lo ancho."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Para medir el largo del salón con pasos, ¿qué cuidas?', '{"options":["Que todos los pasos sean iguales","Que los pasos sean muy rápidos","Que el salón esté bien barrido","Que empieces con el pie derecho"],"correctIndex":0,"ayuda":{"pista":"Lo que se cuida al medir es que la manera de medir no cambie a mitad de camino.","pasos":["Si mides con algo del cuerpo, esa medida tiene que ser siempre del mismo tamaño.","Si comparas dos cosas, las dos se miden con el mismo instrumento.","Si mides cuánto dura algo, hacen falta los dos momentos: cuándo empieza y cuándo acaba."],"ojo":"Medir bien no es medir rápido: es medir siempre de la misma manera."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Para pesar dos frutas y compararlas, ¿qué cuidas?', '{"options":["Que las pongas en la misma balanza","Que las pongas en el mismo plato","Que las dos sean del mismo color","Que las peses el mismo día"],"correctIndex":0,"ayuda":{"pista":"Lo que se cuida al medir es que la manera de medir no cambie a mitad de camino.","pasos":["Si mides con algo del cuerpo, esa medida tiene que ser siempre del mismo tamaño.","Si comparas dos cosas, las dos se miden con el mismo instrumento.","Si mides cuánto dura algo, hacen falta los dos momentos: cuándo empieza y cuándo acaba."],"ojo":"Medir bien no es medir rápido: es medir siempre de la misma manera."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Para medir cuánto dura un juego, ¿qué necesitas?', '{"options":["La hora de empezar y la de terminar","La hora de terminar solamente","La hora de empezar solamente","La hora que marca el reloj ahora"],"correctIndex":0,"ayuda":{"pista":"Lo que se cuida al medir es que la manera de medir no cambie a mitad de camino.","pasos":["Si mides con algo del cuerpo, esa medida tiene que ser siempre del mismo tamaño.","Si comparas dos cosas, las dos se miden con el mismo instrumento.","Si mides cuánto dura algo, hacen falta los dos momentos: cuándo empieza y cuándo acaba."],"ojo":"Medir bien no es medir rápido: es medir siempre de la misma manera."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Mides una cinta con clips y te sobra un pedacito.', '{"options":["Digo «casi 7 clips»","Digo «exactamente 7 clips»","Digo «ningún clip»","Digo «el pedacito no cuenta»"],"correctIndex":0,"ayuda":{"pista":"Cuando la unidad no cabe un número exacto de veces, la medida es aproximada, no falsa.","pasos":["Cuenta cuántas unidades completas caben.","Si sobra un pedacito, la medida está entre ese número y el siguiente.","Se dice «casi» o «un poco más de», que es la verdad."],"ojo":"Decir un número exacto cuando sobró un pedazo es decir algo que no es cierto."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Mides con cuartas y a tu amigo le dan más cuartas.', '{"options":["Su cuarta es más pequeña","Su cuarta es más grande","Midió mal, seguro","Los dos midieron cosas iguales"],"correctIndex":0,"ayuda":{"pista":"Cuando la unidad no cabe un número exacto de veces, la medida es aproximada, no falsa.","pasos":["Cuenta cuántas unidades completas caben.","Si sobra un pedacito, la medida está entre ese número y el siguiente.","Se dice «casi» o «un poco más de», que es la verdad."],"ojo":"Decir un número exacto cuando sobró un pedazo es decir algo que no es cierto."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Mides el mismo escritorio con pasos y con cuartas.', '{"options":["Me dan números distintos","Me dan el mismo número","Me da cero con las cuartas","No se puede medir de dos modos"],"correctIndex":0,"ayuda":{"pista":"Cuando la unidad no cabe un número exacto de veces, la medida es aproximada, no falsa.","pasos":["Cuenta cuántas unidades completas caben.","Si sobra un pedacito, la medida está entre ese número y el siguiente.","Se dice «casi» o «un poco más de», que es la verdad."],"ojo":"Decir un número exacto cuando sobró un pedazo es decir algo que no es cierto."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e9c1120b-d08d-546a-872d-3dccbd367660'::uuid, 'multiple_choice', 'La mesa da 8 cuartas y el escritorio 6. ¿Cuál es más largo?', '{"options":["La mesa","El escritorio","Los dos miden lo mismo","Falta saber de quién es la cuarta"],"correctIndex":0,"ayuda":{"pista":"Dos medidas solo se pueden comparar si están hechas con la MISMA unidad.","pasos":["Mira si las dos medidas se tomaron con lo mismo.","Si es la misma unidad, el que tenga más unidades es el más largo.","Si cada uno midió con su propia cuarta o su propio paso, no se pueden comparar."],"ojo":"Más unidades no siempre es más largo: puede ser que la unidad fuera más pequeña."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e9c1120b-d08d-546a-872d-3dccbd367660'::uuid, 'multiple_choice', 'La cuerda da 5 pasos y la cinta 5 pasos. ¿Cuál es más larga?', '{"options":["Las dos miden lo mismo","La cuerda","La cinta","Falta saber de quién es el paso"],"correctIndex":0,"ayuda":{"pista":"Dos medidas solo se pueden comparar si están hechas con la MISMA unidad.","pasos":["Mira si las dos medidas se tomaron con lo mismo.","Si es la misma unidad, el que tenga más unidades es el más largo.","Si cada uno midió con su propia cuarta o su propio paso, no se pueden comparar."],"ojo":"Más unidades no siempre es más largo: puede ser que la unidad fuera más pequeña."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e9c1120b-d08d-546a-872d-3dccbd367660'::uuid, 'multiple_choice', 'Tu mesa da 8 cuartas y la de Luis 7 cuartas de él.', '{"options":["Las cuartas no son del mismo tamaño","La mesa tuya es más larga","La mesa de Luis es más larga","Las dos mesas miden lo mismo"],"correctIndex":0,"ayuda":{"pista":"Dos medidas solo se pueden comparar si están hechas con la MISMA unidad.","pasos":["Mira si las dos medidas se tomaron con lo mismo.","Si es la misma unidad, el que tenga más unidades es el más largo.","Si cada uno midió con su propia cuarta o su propio paso, no se pueden comparar."],"ojo":"Más unidades no siempre es más largo: puede ser que la unidad fuera más pequeña."}}'::jsonb, 5);
