insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3065d279-0d36-5e09-8db5-61dae1ec586c'::uuid, 'multiple_choice', '¿Cuál de estos pesa cerca de un kilo?', '{"options":["Un paquete de arroz","Una moneda de $500","Una hoja de cuaderno","Un bus de colegio"],"correctIndex":0,"ayuda":{"pista":"Piensa en cosas que hayas cargado y compáralas con lo que te preguntan.","pasos":["Descarta primero lo muchísimo más pequeño.","Descarta lo muchísimo más grande.","De lo que queda, escoge lo que se parezca a algo que ya conozcas de ese tamaño."],"ojo":"Estimar es comparar con algo conocido, no adivinar."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3065d279-0d36-5e09-8db5-61dae1ec586c'::uuid, 'multiple_choice', '¿Cuál de estos mide cerca de un metro?', '{"options":["Una puerta de ancho","Una moneda de $500","Una hoja de cuaderno","Una cancha de fútbol"],"correctIndex":0,"ayuda":{"pista":"Piensa en cosas que hayas cargado y compáralas con lo que te preguntan.","pasos":["Descarta primero lo muchísimo más pequeño.","Descarta lo muchísimo más grande.","De lo que queda, escoge lo que se parezca a algo que ya conozcas de ese tamaño."],"ojo":"Estimar es comparar con algo conocido, no adivinar."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3065d279-0d36-5e09-8db5-61dae1ec586c'::uuid, 'multiple_choice', '¿Cuál de estos dura cerca de un minuto?', '{"options":["Un cepillado de dientes","Un parpadeo","Un día de colegio","Unas vacaciones de mitad de año"],"correctIndex":0,"ayuda":{"pista":"Piensa en cosas que hayas cargado y compáralas con lo que te preguntan.","pasos":["Descarta primero lo muchísimo más pequeño.","Descarta lo muchísimo más grande.","De lo que queda, escoge lo que se parezca a algo que ya conozcas de ese tamaño."],"ojo":"Estimar es comparar con algo conocido, no adivinar."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3065d279-0d36-5e09-8db5-61dae1ec586c'::uuid, 'multiple_choice', 'El salón mide 6 metros. ¿Cuánto medirá el pasillo?', '{"options":["Como 12 metros","Como 120 metros","Como 1.200 metros","Como 12 centímetros"],"correctIndex":0,"ayuda":{"pista":"Usa lo que ya mediste como referencia y pregúntate cuántas veces cabría.","pasos":["Ya sabes cuánto mide una cosa: ese es tu punto de partida.","Piensa si lo otro es parecido, el doble, o muchísimo más.","Escoge la medida que quede en ese rango."],"ojo":"Cambiar de unidad cambia el número: 12 metros y 12 centímetros no se parecen en nada."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3065d279-0d36-5e09-8db5-61dae1ec586c'::uuid, 'multiple_choice', 'Una arepa pesa 100 gramos. ¿Cuánto pesarán diez?', '{"options":["Como un kilo","Como diez kilos","Como cien kilos","Como un gramo"],"correctIndex":0,"ayuda":{"pista":"Usa lo que ya mediste como referencia y pregúntate cuántas veces cabría.","pasos":["Ya sabes cuánto mide una cosa: ese es tu punto de partida.","Piensa si lo otro es parecido, el doble, o muchísimo más.","Escoge la medida que quede en ese rango."],"ojo":"Cambiar de unidad cambia el número: 12 metros y 12 centímetros no se parecen en nada."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3065d279-0d36-5e09-8db5-61dae1ec586c'::uuid, 'multiple_choice', 'Un recreo dura 20 minutos. ¿Cuánto durarán tres?', '{"options":["Como una hora","Como un minuto","Como un día","Como una semana"],"correctIndex":0,"ayuda":{"pista":"Usa lo que ya mediste como referencia y pregúntate cuántas veces cabría.","pasos":["Ya sabes cuánto mide una cosa: ese es tu punto de partida.","Piensa si lo otro es parecido, el doble, o muchísimo más.","Escoge la medida que quede en ese rango."],"ojo":"Cambiar de unidad cambia el número: 12 metros y 12 centímetros no se parecen en nada."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', 'Tienes que medir el ancho de una hoja. ¿Qué te sirve?', '{"options":["Una regla","Una balanza","Un calendario","Una jarra marcada"],"correctIndex":0,"ayuda":{"pista":"Escoge el instrumento por lo que vas a averiguar, no por el objeto.","pasos":["Un ancho es una longitud: necesitas algo con marcas de largo.","Un día es tiempo: necesitas algo que cuente días.","Repartir un líquido necesita algo con marcas de cuánto cabe."],"ojo":"El mismo objeto se puede medir de varias maneras según qué le preguntes."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', 'Tienes que saber qué día cae tu cumpleaños. ¿Qué usas?', '{"options":["Un calendario","Una regla","Una balanza","Una jarra marcada"],"correctIndex":0,"ayuda":{"pista":"Escoge el instrumento por lo que vas a averiguar, no por el objeto.","pasos":["Un ancho es una longitud: necesitas algo con marcas de largo.","Un día es tiempo: necesitas algo que cuente días.","Repartir un líquido necesita algo con marcas de cuánto cabe."],"ojo":"El mismo objeto se puede medir de varias maneras según qué le preguntes."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('718cb144-958b-5bbe-89db-4464cd1189af'::uuid, 'multiple_choice', 'Tienes que repartir jugo en partes iguales. ¿Qué usas?', '{"options":["Una jarra marcada","Un calendario","Una regla","Una balanza"],"correctIndex":0,"ayuda":{"pista":"Escoge el instrumento por lo que vas a averiguar, no por el objeto.","pasos":["Un ancho es una longitud: necesitas algo con marcas de largo.","Un día es tiempo: necesitas algo que cuente días.","Repartir un líquido necesita algo con marcas de cuánto cabe."],"ojo":"El mismo objeto se puede medir de varias maneras según qué le preguntes."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Vas a medir el largo de la cancha. ¿Por dónde empiezas?', '{"options":["Pongo el cero justo en la orilla","Pongo el cero por la mitad","Empiezo por donde me quede","Empiezo por el otro extremo"],"correctIndex":0,"ayuda":{"pista":"Antes de medir hay que poner el punto de partida en su sitio.","pasos":["Si es longitud, el cero va justo donde empieza lo que vas a medir.","Si es peso, la aguja tiene que estar en cero antes de poner nada.","Si es tiempo, hay que mirar el reloj al empezar y también al terminar."],"ojo":"Empezar mal el conteo daña toda la medida, aunque después lo hagas todo bien."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Vas a pesar una fruta en la balanza. ¿Qué miras antes?', '{"options":["Que la aguja marque cero","Que la aguja marque uno","Que la fruta esté madura","Que la fruta esté lavada"],"correctIndex":0,"ayuda":{"pista":"Antes de medir hay que poner el punto de partida en su sitio.","pasos":["Si es longitud, el cero va justo donde empieza lo que vas a medir.","Si es peso, la aguja tiene que estar en cero antes de poner nada.","Si es tiempo, hay que mirar el reloj al empezar y también al terminar."],"ojo":"Empezar mal el conteo daña toda la medida, aunque después lo hagas todo bien."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('94f29393-ccae-54e9-8b36-51b148f62de8'::uuid, 'multiple_choice', 'Vas a medir cuánto tardas en llegar. ¿Qué haces?', '{"options":["Miro la hora al salir y al llegar","Miro la hora solo al llegar","Miro la hora solo al salir","Cuento los pasos del camino"],"correctIndex":0,"ayuda":{"pista":"Antes de medir hay que poner el punto de partida en su sitio.","pasos":["Si es longitud, el cero va justo donde empieza lo que vas a medir.","Si es peso, la aguja tiene que estar en cero antes de poner nada.","Si es tiempo, hay que mirar el reloj al empezar y también al terminar."],"ojo":"Empezar mal el conteo daña toda la medida, aunque después lo hagas todo bien."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select 'd709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, d.id, 1, 'Describe objetos y eventos de acuerdo con atributos medibles: superficie, tiempo, longitud, peso, ángulos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 5;
insert into learning_evidences (id, dba_id, num, texto) select '894b8e23-44ed-53ee-83a2-49f2a8fa0d07'::uuid, d.id, 2, 'Realiza mediciones con instrumentos y unidades no convencionales, como pasos, cuadrados o rectángulos, cuartas, metros, entre otros.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 5;
insert into learning_evidences (id, dba_id, num, texto) select 'e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, d.id, 3, 'Compara eventos según su duración, para ello utiliza relojes convencionales.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 5;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', 'De una cancha de fútbol, ¿qué se mide con pasos?', '{"options":["Lo que hay de arco a arco","Lo que se demora un partido","Lo que pesa cada jugador","Lo que cuesta la entrada"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento mide una cosa distinta: pregúntate cuál de ellas estás nombrando.","pasos":["Los pasos y las cuartas miden distancias.","Los recipientes con marcas miden lo que cabe.","Los relojes miden lo que dura."],"ojo":"De un mismo objeto se pueden medir varias cosas: largo, peso, duración."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', 'De una piscina, ¿qué se mide con una jarra marcada?', '{"options":["El agua que le cabe","El tiempo que abre al día","Los metros que tiene de fondo","Las personas que entran"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento mide una cosa distinta: pregúntate cuál de ellas estás nombrando.","pasos":["Los pasos y las cuartas miden distancias.","Los recipientes con marcas miden lo que cabe.","Los relojes miden lo que dura."],"ojo":"De un mismo objeto se pueden medir varias cosas: largo, peso, duración."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', 'De una película, ¿qué se mide con un reloj?', '{"options":["Lo que se demora en pasar","Lo que mide la pantalla","Lo que pesa el proyector","Lo que vale el boleto"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento mide una cosa distinta: pregúntate cuál de ellas estás nombrando.","pasos":["Los pasos y las cuartas miden distancias.","Los recipientes con marcas miden lo que cabe.","Los relojes miden lo que dura."],"ojo":"De un mismo objeto se pueden medir varias cosas: largo, peso, duración."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', 'Cubres el piso con baldosas para saber su superficie.', '{"options":["Cuento las baldosas que caben","Mido el borde de una baldosa","Peso una baldosa en la balanza","Cuento las baldosas de un lado"],"correctIndex":0,"ayuda":{"pista":"La superficie se mide CUBRIENDO, no rodeando ni pesando.","pasos":["Para saber cuánto cubre algo, se cuenta cuántas piezas iguales caben encima.","Para saber cuánto lo rodea, se mide el borde y se suma.","Son dos preguntas distintas y dan números distintos."],"ojo":"Contar las piezas de un solo lado da el largo, no la superficie."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', 'Quieres saber cuánto papel cubre la mesa.', '{"options":["Cuento los cuadrados que caben","Mido el borde de un cuadrado","Peso el papel en la balanza","Cuento los cuadrados de un lado"],"correctIndex":0,"ayuda":{"pista":"La superficie se mide CUBRIENDO, no rodeando ni pesando.","pasos":["Para saber cuánto cubre algo, se cuenta cuántas piezas iguales caben encima.","Para saber cuánto lo rodea, se mide el borde y se suma.","Son dos preguntas distintas y dan números distintos."],"ojo":"Contar las piezas de un solo lado da el largo, no la superficie."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', 'Quieres saber cuánta cinta rodea el cuaderno.', '{"options":["Mido todo el borde y lo sumo","Cuento los cuadrados que caben","Peso el cuaderno en la balanza","Mido solo el lado más largo"],"correctIndex":0,"ayuda":{"pista":"La superficie se mide CUBRIENDO, no rodeando ni pesando.","pasos":["Para saber cuánto cubre algo, se cuenta cuántas piezas iguales caben encima.","Para saber cuánto lo rodea, se mide el borde y se suma.","Son dos preguntas distintas y dan números distintos."],"ojo":"Contar las piezas de un solo lado da el largo, no la superficie."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('894b8e23-44ed-53ee-83a2-49f2a8fa0d07'::uuid, 'multiple_choice', 'El salón da 20 pasos tuyos y 25 pasos de Ana.', '{"options":["El paso de Ana es más corto","El paso de Ana es más largo","El salón cambió de tamaño","Alguno de los dos contó mal"],"correctIndex":0,"ayuda":{"pista":"Si el mismo espacio da más unidades, es porque esa unidad es más pequeña.","pasos":["El salón no cambió de tamaño: los dos midieron lo mismo.","El que necesitó más pasos los tiene más cortos.","El que necesitó menos, los tiene más largos."],"ojo":"Un número más grande no significa un espacio más grande si la unidad cambió."}}'::jsonb, 3);
