insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', '¿Qué hora marca el reloj?', '{"options":["3:00","12:03","6:00","3:30"],"correctIndex":0,"visual":{"tipo":"reloj","hora":3,"minuto":0},"ayuda":{"pista":"La manecilla corta dice la hora y la larga dice los minutos.","pasos":["Busca la manecilla corta: la hora es el número que ya pasó, no el que viene.","Busca la larga y cuenta de 5 en 5 desde el 12 hasta donde apunta.","Primero se dice la hora y después los minutos."],"ojo":"Leer la manecilla larga como si fuera la hora es el error más común."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', '¿Qué hora marca el reloj?', '{"options":["6:30","12:30","6:06","7:30"],"correctIndex":0,"visual":{"tipo":"reloj","hora":6,"minuto":30},"ayuda":{"pista":"La manecilla corta dice la hora y la larga dice los minutos.","pasos":["Busca la manecilla corta: la hora es el número que ya pasó, no el que viene.","Busca la larga y cuenta de 5 en 5 desde el 12 hasta donde apunta.","Primero se dice la hora y después los minutos."],"ojo":"Leer la manecilla larga como si fuera la hora es el error más común."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', '¿Qué hora marca el reloj?', '{"options":["9:15","3:45","9:03","12:09"],"correctIndex":0,"visual":{"tipo":"reloj","hora":9,"minuto":15},"ayuda":{"pista":"La manecilla corta dice la hora y la larga dice los minutos.","pasos":["Busca la manecilla corta: la hora es el número que ya pasó, no el que viene.","Busca la larga y cuenta de 5 en 5 desde el 12 hasta donde apunta.","Primero se dice la hora y después los minutos."],"ojo":"Leer la manecilla larga como si fuera la hora es el error más común."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Mira las manecillas. ¿Qué hora es?', '{"options":["7:45","9:35","8:45","7:09"],"correctIndex":0,"visual":{"tipo":"reloj","hora":7,"minuto":45},"ayuda":{"pista":"Fíjate en cuál manecilla es la corta: esa manda para la hora.","pasos":["La manecilla de las horas va despacio y casi nunca apunta a un número exacto.","Si está entre dos números, la hora es el MENOR de los dos.","La manecilla larga se lee contando de 5 en 5 desde el 12."],"ojo":"Pasada la media hora, la corta ya casi toca el número siguiente y confunde."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Mira las manecillas. ¿Qué hora es?', '{"options":["10:20","4:50","10:04","11:20"],"correctIndex":0,"visual":{"tipo":"reloj","hora":10,"minuto":20},"ayuda":{"pista":"Fíjate en cuál manecilla es la corta: esa manda para la hora.","pasos":["La manecilla de las horas va despacio y casi nunca apunta a un número exacto.","Si está entre dos números, la hora es el MENOR de los dos.","La manecilla larga se lee contando de 5 en 5 desde el 12."],"ojo":"Pasada la media hora, la corta ya casi toca el número siguiente y confunde."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Mira las manecillas. ¿Qué hora es?', '{"options":["1:50","10:05","2:50","1:10"],"correctIndex":0,"visual":{"tipo":"reloj","hora":1,"minuto":50},"ayuda":{"pista":"Fíjate en cuál manecilla es la corta: esa manda para la hora.","pasos":["La manecilla de las horas va despacio y casi nunca apunta a un número exacto.","Si está entre dos números, la hora es el MENOR de los dos.","La manecilla larga se lee contando de 5 en 5 desde el 12."],"ojo":"Pasada la media hora, la corta ya casi toca el número siguiente y confunde."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Pipe sale a las 8:00 y llega a las 8:30. ¿Cuánto tardó?', '{"options":["30 minutos","8 minutos","30 horas","1 hora"],"correctIndex":0,"ayuda":{"pista":"La duración es lo que hay entre la hora de salida y la de llegada.","pasos":["Mira a qué hora empezó y a qué hora terminó.","Si la hora es la misma, la diferencia está solo en los minutos.","Si cambió la hora, cada hora completa son 60 minutos."],"ojo":"La hora de llegada no es la duración: es el momento en que terminó."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Lupe sale a las 8:00 y llega a las 8:35. ¿Cuánto tardó?', '{"options":["35 minutos","8 minutos","35 horas","1 hora"],"correctIndex":0,"ayuda":{"pista":"La duración es lo que hay entre la hora de salida y la de llegada.","pasos":["Mira a qué hora empezó y a qué hora terminó.","Si la hora es la misma, la diferencia está solo en los minutos.","Si cambió la hora, cada hora completa son 60 minutos."],"ojo":"La hora de llegada no es la duración: es el momento en que terminó."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Ana sale a las 2:00 y llega a las 3:00. ¿Cuánto tardó?', '{"options":["1 hora","3 horas","2 horas","30 minutos"],"correctIndex":0,"ayuda":{"pista":"La duración es lo que hay entre la hora de salida y la de llegada.","pasos":["Mira a qué hora empezó y a qué hora terminó.","Si la hora es la misma, la diferencia está solo en los minutos.","Si cambió la hora, cada hora completa son 60 minutos."],"ojo":"La hora de llegada no es la duración: es el momento en que terminó."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Salen juntos. Pipe tarda 30 min y Lupe 35 min. ¿Quién llegó antes?', '{"options":["Pipe, porque tardó menos","Lupe, porque tardó menos","Pipe y Lupe llegaron juntos","Falta saber cuándo salieron"],"correctIndex":0,"ayuda":{"pista":"Si salieron a la misma hora, llegó primero el que tardó menos.","pasos":["Comprueba primero si de verdad salieron al mismo tiempo.","Si salieron juntos, basta con comparar cuánto tardó cada uno.","Si no salieron juntos, tardar menos ya no alcanza para saber quién llegó primero."],"ojo":"Tardar menos y llegar antes solo son lo mismo cuando los dos arrancaron juntos."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Salen juntos. Pipe tarda 40 min y Lupe 25 min. ¿Quién llegó antes?', '{"options":["Lupe, porque tardó menos","Pipe, porque tardó menos","Pipe y Lupe llegaron juntos","Falta saber cuándo salieron"],"correctIndex":0,"ayuda":{"pista":"Si salieron a la misma hora, llegó primero el que tardó menos.","pasos":["Comprueba primero si de verdad salieron al mismo tiempo.","Si salieron juntos, basta con comparar cuánto tardó cada uno.","Si no salieron juntos, tardar menos ya no alcanza para saber quién llegó primero."],"ojo":"Tardar menos y llegar antes solo son lo mismo cuando los dos arrancaron juntos."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e7cb00a9-d0d8-59b6-8f75-5ef59c7d145f'::uuid, 'multiple_choice', 'Pipe tarda 30 min y Lupe 35 min, pero no salieron juntos.', '{"options":["Falta saber cuándo salió cada uno","Pipe, porque tardó menos","Lupe, porque tardó menos","Pipe y Lupe llegaron juntos"],"correctIndex":0,"ayuda":{"pista":"Si salieron a la misma hora, llegó primero el que tardó menos.","pasos":["Comprueba primero si de verdad salieron al mismo tiempo.","Si salieron juntos, basta con comparar cuánto tardó cada uno.","Si no salieron juntos, tardar menos ya no alcanza para saber quién llegó primero."],"ojo":"Tardar menos y llegar antes solo son lo mismo cuando los dos arrancaron juntos."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', '¿Qué le mides a una puerta si te preguntan su alto?', '{"options":["Lo que hay del piso al techo","Lo que hay de un lado al otro","Lo que pesa cuando la cargas","Lo que tarda en cerrarse"],"correctIndex":0,"ayuda":{"pista":"Cada palabra —alto, capacidad, peso— nombra una cosa distinta que medir.","pasos":["El alto es una distancia: va de abajo hacia arriba.","La capacidad es lo que le cabe adentro.","El peso es lo que marca la balanza cuando lo pones encima."],"ojo":"Un objeto grande no siempre es pesado, y uno pesado no siempre es grande."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', '¿Qué le mides a un vaso si te preguntan su capacidad?', '{"options":["Lo que le cabe de agua","Lo que hay del piso al borde","Lo que pesa estando vacío","Lo que tarda en llenarse"],"correctIndex":0,"ayuda":{"pista":"Cada palabra —alto, capacidad, peso— nombra una cosa distinta que medir.","pasos":["El alto es una distancia: va de abajo hacia arriba.","La capacidad es lo que le cabe adentro.","El peso es lo que marca la balanza cuando lo pones encima."],"ojo":"Un objeto grande no siempre es pesado, y uno pesado no siempre es grande."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d709e872-6ce6-5df5-81c4-5cfcd5ab6db8'::uuid, 'multiple_choice', '¿Qué le mides a una caja si te preguntan su peso?', '{"options":["Lo que marca la balanza","Lo que hay del piso a la tapa","Lo que le cabe de agua","Lo que tarda en llenarse"],"correctIndex":0,"ayuda":{"pista":"Cada palabra —alto, capacidad, peso— nombra una cosa distinta que medir.","pasos":["El alto es una distancia: va de abajo hacia arriba.","La capacidad es lo que le cabe adentro.","El peso es lo que marca la balanza cuando lo pones encima."],"ojo":"Un objeto grande no siempre es pesado, y uno pesado no siempre es grande."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select 'e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, d.id, 1, 'Reconoce las figuras geométricas según el número de lados.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 6;
