insert into learning_evidences (id, dba_id, num, texto) select 'f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, d.id, 3, 'Compara figuras y cuerpos geométricos y establece relaciones y diferencias entre ambos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 6;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuál de estas figuras tiene cuatro lados iguales?', '{"options":["cuadrado","triángulo","círculo","rectángulo"],"correctIndex":0,"figuras":["cuadrado","triángulo","círculo","rectángulo"],"ayuda":{"pista":"Cuenta los lados de cada figura y, si hace falta, mira si miden lo mismo.","pasos":["Un lado es cada tramo recto del borde.","Cuenta los lados de cada figura antes de decidir.","Si varias tienen el mismo número de lados, mira si miden todos igual."],"ojo":"Cuatro lados no basta: el rectángulo también tiene cuatro y no son todos iguales."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuál de estas figuras no tiene ningún lado recto?', '{"options":["círculo","cuadrado","triángulo","rectángulo"],"correctIndex":0,"figuras":["círculo","cuadrado","triángulo","rectángulo"],"ayuda":{"pista":"Cuenta los lados de cada figura y, si hace falta, mira si miden lo mismo.","pasos":["Un lado es cada tramo recto del borde.","Cuenta los lados de cada figura antes de decidir.","Si varias tienen el mismo número de lados, mira si miden todos igual."],"ojo":"Cuatro lados no basta: el rectángulo también tiene cuatro y no son todos iguales."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuál de estas figuras tiene tres lados?', '{"options":["triángulo","cuadrado","círculo","rectángulo"],"correctIndex":0,"figuras":["triángulo","cuadrado","círculo","rectángulo"],"ayuda":{"pista":"Cuenta los lados de cada figura y, si hace falta, mira si miden lo mismo.","pasos":["Un lado es cada tramo recto del borde.","Cuenta los lados de cada figura antes de decidir.","Si varias tienen el mismo número de lados, mira si miden todos igual."],"ojo":"Cuatro lados no basta: el rectángulo también tiene cuatro y no son todos iguales."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', 'Una figura tiene 4 lados y dos son más largos.', '{"options":["rectángulo","cuadrado","triángulo","círculo"],"correctIndex":0,"figuras":["rectángulo","cuadrado","triángulo","círculo"],"ayuda":{"pista":"Lee la descripción entera y descarta las figuras que incumplan alguna parte.","pasos":["Empieza por el número de lados: eso ya descarta varias.","Después mira si dice algo sobre el tamaño de los lados.","La figura buena es la que cumple TODO lo que dice, no solo lo primero."],"ojo":"Quedarse con la primera pista es lo que hace confundir el cuadrado con el rectángulo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', 'Una figura tiene 4 esquinas y todos sus lados iguales.', '{"options":["cuadrado","rectángulo","triángulo","círculo"],"correctIndex":0,"figuras":["cuadrado","rectángulo","triángulo","círculo"],"ayuda":{"pista":"Lee la descripción entera y descarta las figuras que incumplan alguna parte.","pasos":["Empieza por el número de lados: eso ya descarta varias.","Después mira si dice algo sobre el tamaño de los lados.","La figura buena es la que cumple TODO lo que dice, no solo lo primero."],"ojo":"Quedarse con la primera pista es lo que hace confundir el cuadrado con el rectángulo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', 'Una figura tiene 3 esquinas y 3 lados rectos.', '{"options":["triángulo","cuadrado","rectángulo","círculo"],"correctIndex":0,"figuras":["triángulo","cuadrado","rectángulo","círculo"],"ayuda":{"pista":"Lee la descripción entera y descarta las figuras que incumplan alguna parte.","pasos":["Empieza por el número de lados: eso ya descarta varias.","Después mira si dice algo sobre el tamaño de los lados.","La figura buena es la que cumple TODO lo que dice, no solo lo primero."],"ojo":"Quedarse con la primera pista es lo que hace confundir el cuadrado con el rectángulo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuántos lados tiene un rectángulo?', '{"options":["4","3","5","6"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"rectángulo"},"ayuda":{"pista":"Recorre el borde con el dedo y cuenta cada tramo recto, sin repetir ninguno.","pasos":["Empieza en una esquina y ve siguiendo el borde.","Cada tramo recto entre dos esquinas es un lado.","Vuelves a la esquina de partida cuando ya los contaste todos."],"ojo":"En estas figuras hay tantos lados como esquinas: si te dan distinto, contaste mal."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuántas esquinas tiene un triángulo?', '{"options":["3","4","5","6"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"triángulo"},"ayuda":{"pista":"Recorre el borde con el dedo y cuenta cada tramo recto, sin repetir ninguno.","pasos":["Empieza en una esquina y ve siguiendo el borde.","Cada tramo recto entre dos esquinas es un lado.","Vuelves a la esquina de partida cuando ya los contaste todos."],"ojo":"En estas figuras hay tantos lados como esquinas: si te dan distinto, contaste mal."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuántos lados tiene un cuadrado?', '{"options":["4","3","6","8"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"cuadrado"},"ayuda":{"pista":"Recorre el borde con el dedo y cuenta cada tramo recto, sin repetir ninguno.","pasos":["Empieza en una esquina y ve siguiendo el borde.","Cada tramo recto entre dos esquinas es un lado.","Vuelves a la esquina de partida cuando ya los contaste todos."],"ojo":"En estas figuras hay tantos lados como esquinas: si te dan distinto, contaste mal."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', '¿Cuál de estos cuerpos rueda por todos lados?', '{"options":["esfera","cubo","prisma","pirámide"],"correctIndex":0,"figuras":["esfera","cubo","prisma","pirámide"],"ayuda":{"pista":"Piensa qué tiene ese cuerpo por fuera: caras planas, o superficie curva.","pasos":["Lo que tiene caras planas se queda quieto apoyado en una de ellas.","Lo que es curvo por todas partes no encuentra dónde quedarse quieto.","Algunos tienen las dos cosas y solo ruedan para un lado."],"ojo":"Rodar no depende del tamaño sino de si hay caras planas donde apoyarse."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', '¿Cuál de estos cuerpos tiene una punta sola arriba?', '{"options":["cono","cubo","cilindro","esfera"],"correctIndex":0,"figuras":["cono","cubo","cilindro","esfera"],"ayuda":{"pista":"Piensa qué tiene ese cuerpo por fuera: caras planas, o superficie curva.","pasos":["Lo que tiene caras planas se queda quieto apoyado en una de ellas.","Lo que es curvo por todas partes no encuentra dónde quedarse quieto.","Algunos tienen las dos cosas y solo ruedan para un lado."],"ojo":"Rodar no depende del tamaño sino de si hay caras planas donde apoyarse."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', '¿Cuál de estos cuerpos tiene todas sus caras iguales?', '{"options":["cubo","cono","cilindro","esfera"],"correctIndex":0,"figuras":["cubo","cono","cilindro","esfera"],"ayuda":{"pista":"Piensa qué tiene ese cuerpo por fuera: caras planas, o superficie curva.","pasos":["Lo que tiene caras planas se queda quieto apoyado en una de ellas.","Lo que es curvo por todas partes no encuentra dónde quedarse quieto.","Algunos tienen las dos cosas y solo ruedan para un lado."],"ojo":"Rodar no depende del tamaño sino de si hay caras planas donde apoyarse."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', 'Una lata de gaseosa se parece a un:', '{"options":["cilindro","cubo","cono","prisma"],"correctIndex":0,"figuras":["cilindro","cubo","cono","prisma"],"ayuda":{"pista":"Mírale la forma al objeto: cuántas caras planas tiene y cómo son.","pasos":["Fíjate si tiene caras planas y de qué forma son.","Fíjate si tiene alguna parte curva.","Busca el cuerpo geométrico que tenga esas mismas partes."],"ojo":"Los objetos de verdad nunca son perfectos: se PARECEN a un cuerpo, no son ese cuerpo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', 'Un dado se parece a un:', '{"options":["cubo","cilindro","cono","prisma"],"correctIndex":0,"figuras":["cubo","cilindro","cono","prisma"],"ayuda":{"pista":"Mírale la forma al objeto: cuántas caras planas tiene y cómo son.","pasos":["Fíjate si tiene caras planas y de qué forma son.","Fíjate si tiene alguna parte curva.","Busca el cuerpo geométrico que tenga esas mismas partes."],"ojo":"Los objetos de verdad nunca son perfectos: se PARECEN a un cuerpo, no son ese cuerpo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', 'Una caja de cereal se parece a un:', '{"options":["prisma","cubo","cilindro","cono"],"correctIndex":0,"figuras":["prisma","cubo","cilindro","cono"],"ayuda":{"pista":"Mírale la forma al objeto: cuántas caras planas tiene y cómo son.","pasos":["Fíjate si tiene caras planas y de qué forma son.","Fíjate si tiene alguna parte curva.","Busca el cuerpo geométrico que tenga esas mismas partes."],"ojo":"Los objetos de verdad nunca son perfectos: se PARECEN a un cuerpo, no son ese cuerpo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', '¿Cuántas caras tiene un cubo?', '{"options":["6","4","8","12"],"correctIndex":0,"ayuda":{"pista":"Cara es cada superficie plana; arista, cada línea donde se juntan dos caras; vértice, cada punta.","pasos":["Para las caras, piensa en las tapas: arriba, abajo y los lados.","Para las aristas, cuenta las líneas donde se doblan dos caras.","Para los vértices, cuenta las puntas donde se juntan las líneas."],"ojo":"Caras, aristas y vértices son tres cosas distintas y dan tres números distintos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', '¿Cuántas aristas tiene un cubo?', '{"options":["12","6","8","4"],"correctIndex":0,"ayuda":{"pista":"Cara es cada superficie plana; arista, cada línea donde se juntan dos caras; vértice, cada punta.","pasos":["Para las caras, piensa en las tapas: arriba, abajo y los lados.","Para las aristas, cuenta las líneas donde se doblan dos caras.","Para los vértices, cuenta las puntas donde se juntan las líneas."],"ojo":"Caras, aristas y vértices son tres cosas distintas y dan tres números distintos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('58346420-acfe-5889-8d63-3e6e76bcdc8b'::uuid, 'multiple_choice', '¿Cuántos vértices tiene un cubo?', '{"options":["8","6","12","4"],"correctIndex":0,"ayuda":{"pista":"Cara es cada superficie plana; arista, cada línea donde se juntan dos caras; vértice, cada punta.","pasos":["Para las caras, piensa en las tapas: arriba, abajo y los lados.","Para las aristas, cuenta las líneas donde se doblan dos caras.","Para los vértices, cuenta las puntas donde se juntan las líneas."],"ojo":"Caras, aristas y vértices son tres cosas distintas y dan tres números distintos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', 'Si mojas una cara del cubo y la estampas, ¿qué sale?', '{"options":["un cuadrado","un triángulo","un círculo","un rectángulo"],"correctIndex":0,"ayuda":{"pista":"Lo que queda estampado es la forma PLANA de esa cara.","pasos":["Mira qué forma tiene la cara que vas a estampar.","El sello deja esa forma plana, no el cuerpo entero.","Por eso un cuerpo puede dejar sellos distintos según qué cara uses."],"ojo":"El sello nunca sale con volumen: un cuerpo deja siempre una figura plana."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', 'Si mojas la base del cono y la estampas, ¿qué sale?', '{"options":["un círculo","un cuadrado","un triángulo","un rectángulo"],"correctIndex":0,"ayuda":{"pista":"Lo que queda estampado es la forma PLANA de esa cara.","pasos":["Mira qué forma tiene la cara que vas a estampar.","El sello deja esa forma plana, no el cuerpo entero.","Por eso un cuerpo puede dejar sellos distintos según qué cara uses."],"ojo":"El sello nunca sale con volumen: un cuerpo deja siempre una figura plana."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', 'Si mojas la base del cilindro y la estampas, ¿qué sale?', '{"options":["un círculo","un cuadrado","un triángulo","un rectángulo"],"correctIndex":0,"ayuda":{"pista":"Lo que queda estampado es la forma PLANA de esa cara.","pasos":["Mira qué forma tiene la cara que vas a estampar.","El sello deja esa forma plana, no el cuerpo entero.","Por eso un cuerpo puede dejar sellos distintos según qué cara uses."],"ojo":"El sello nunca sale con volumen: un cuerpo deja siempre una figura plana."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', '¿En qué se diferencia un cuadrado de un cubo?', '{"options":["El cubo se puede llenar","El cubo tiene menos esquinas","El cuadrado se puede llenar","El cuadrado tiene más caras"],"correctIndex":0,"ayuda":{"pista":"Uno es plano y el otro ocupa lugar: piensa si se puede llenar o solo dibujar.","pasos":["Las figuras planas se dibujan en una hoja y no tienen adentro.","Los cuerpos ocupan espacio, se pueden llenar y se pueden agarrar.","Las caras de un cuerpo SON figuras planas: por ahí se relacionan."],"ojo":"Que tengan nombres parecidos no los vuelve lo mismo: uno cabe en una hoja y el otro no."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', '¿En qué se diferencia un círculo de una esfera?', '{"options":["La esfera se puede llenar","La esfera tiene menos bordes","El círculo se puede llenar","El círculo rueda por todos lados"],"correctIndex":0,"ayuda":{"pista":"Uno es plano y el otro ocupa lugar: piensa si se puede llenar o solo dibujar.","pasos":["Las figuras planas se dibujan en una hoja y no tienen adentro.","Los cuerpos ocupan espacio, se pueden llenar y se pueden agarrar.","Las caras de un cuerpo SON figuras planas: por ahí se relacionan."],"ojo":"Que tengan nombres parecidos no los vuelve lo mismo: uno cabe en una hoja y el otro no."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', '¿En qué se parecen un cuadrado y la cara de un cubo?', '{"options":["Los dos tienen cuatro lados","Los dos se pueden llenar","Los dos tienen seis caras","Los dos ruedan por el piso"],"correctIndex":0,"ayuda":{"pista":"Uno es plano y el otro ocupa lugar: piensa si se puede llenar o solo dibujar.","pasos":["Las figuras planas se dibujan en una hoja y no tienen adentro.","Los cuerpos ocupan espacio, se pueden llenar y se pueden agarrar.","Las caras de un cuerpo SON figuras planas: por ahí se relacionan."],"ojo":"Que tengan nombres parecidos no los vuelve lo mismo: uno cabe en una hoja y el otro no."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', 'Andrés escribe: «mi balón tiene forma de cubo». ¿Está bien?', '{"options":["No: un balón no tiene caras planas","Sí: el balón tiene seis caras","No: un balón no rueda nunca","Sí: el cubo rueda como el balón"],"correctIndex":0,"ayuda":{"pista":"Comprueba si el objeto de verdad tiene las partes que ese nombre promete.","pasos":["Piensa qué partes tiene el cuerpo que él nombró.","Piensa qué partes tiene el objeto de verdad.","Si no coinciden, la descripción está mal, y hay que decir por qué."],"ojo":"No alcanza con decir que está mal: hay que señalar en qué parte falla."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', 'Andrés escribe: «mi ventana es un cuadrado». ¿Está bien?', '{"options":["Sí: es plana y de cuatro lados","No: una ventana no es plana","No: el cuadrado no tiene lados","Sí: la ventana se puede llenar"],"correctIndex":0,"ayuda":{"pista":"Comprueba si el objeto de verdad tiene las partes que ese nombre promete.","pasos":["Piensa qué partes tiene el cuerpo que él nombró.","Piensa qué partes tiene el objeto de verdad.","Si no coinciden, la descripción está mal, y hay que decir por qué."],"ojo":"No alcanza con decir que está mal: hay que señalar en qué parte falla."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f7f6cc89-12dc-5b49-8d69-b2d9730c940e'::uuid, 'multiple_choice', 'Andrés escribe: «mi cama es una esfera». ¿Está bien?', '{"options":["No: la cama no rueda por el piso","Sí: la cama tiene forma redonda","No: la esfera tiene cuatro lados","Sí: las dos cosas son planas"],"correctIndex":0,"ayuda":{"pista":"Comprueba si el objeto de verdad tiene las partes que ese nombre promete.","pasos":["Piensa qué partes tiene el cuerpo que él nombró.","Piensa qué partes tiene el objeto de verdad.","Si no coinciden, la descripción está mal, y hay que decir por qué."],"ojo":"No alcanza con decir que está mal: hay que señalar en qué parte falla."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuál figura NO tiene esquinas?', '{"options":["círculo","triángulo","cuadrado","rectángulo"],"correctIndex":0,"figuras":["círculo","triángulo","cuadrado","rectángulo"],"ayuda":{"pista":"Ojo con el NO: te están pidiendo la que NO cumple, no la que sí.","pasos":["Lee otra vez la pregunta y fíjate si hay un NO.","Revisa una por una si cumplen o no cumplen.","Escoge la que se sale del grupo, no la que encaja."],"ojo":"Las preguntas con NO se fallan por leerlas rápido, no por no saber la materia."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuál figura tiene más lados que el triángulo?', '{"options":["cuadrado","círculo","triángulo","cono"],"correctIndex":0,"figuras":["cuadrado","círculo","triángulo","cono"],"ayuda":{"pista":"Ojo con el NO: te están pidiendo la que NO cumple, no la que sí.","pasos":["Lee otra vez la pregunta y fíjate si hay un NO.","Revisa una por una si cumplen o no cumplen.","Escoge la que se sale del grupo, no la que encaja."],"ojo":"Las preguntas con NO se fallan por leerlas rápido, no por no saber la materia."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e3ba2545-03bd-5730-821f-1d252d00426c'::uuid, 'multiple_choice', '¿Cuál figura tiene igual número de lados que el cuadrado?', '{"options":["rectángulo","triángulo","círculo","cono"],"correctIndex":0,"figuras":["rectángulo","triángulo","círculo","cono"],"ayuda":{"pista":"Ojo con el NO: te están pidiendo la que NO cumple, no la que sí.","pasos":["Lee otra vez la pregunta y fíjate si hay un NO.","Revisa una por una si cumplen o no cumplen.","Escoge la que se sale del grupo, no la que encaja."],"ojo":"Las preguntas con NO se fallan por leerlas rápido, no por no saber la materia."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, d.id, 1, 'Describe desplazamientos a partir de las posiciones de las líneas.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 7;
