insert into learning_evidences (id, dba_id, num, texto) select 'bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, d.id, 3, 'En dibujos, objetos o espacios reales, identifica posiciones de objetos, de aristas o líneas que son paralelas, verticales o perpendiculares.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 7;
insert into learning_evidences (id, dba_id, num, texto) select '757eebfc-8610-53e1-8309-d1393672499f'::uuid, d.id, 4, 'Argumenta las diferencias entre las posiciones de las líneas.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 7;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fae8527e-b6c6-5e83-837c-4a5ace0ecc90'::uuid, 'multiple_choice', 'Mira la línea del dibujo. ¿Cómo está puesta?', '{"options":["Acostada, como el horizonte","Parada, como un poste","Cruzada en forma de equis","Doblada por la mitad"],"correctIndex":0,"visual":{"tipo":"lineas","clase":"horizontal"},"ayuda":{"pista":"Compara la línea con el marco: mira si va como el suelo, como una pared, o cruzada.","pasos":["Una línea acostada, que va de lado a lado, está horizontal.","Una línea parada, que va de arriba abajo, está vertical.","Dos líneas que van juntas sin tocarse nunca están paralelas."],"ojo":"Horizontal y vertical no existen solas: se dicen siempre comparando con algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fae8527e-b6c6-5e83-837c-4a5ace0ecc90'::uuid, 'multiple_choice', 'Mira la línea del dibujo. ¿Cómo está puesta?', '{"options":["Parada, como un poste","Acostada, como el horizonte","Cruzada en forma de equis","Doblada por la mitad"],"correctIndex":0,"visual":{"tipo":"lineas","clase":"vertical"},"ayuda":{"pista":"Compara la línea con el marco: mira si va como el suelo, como una pared, o cruzada.","pasos":["Una línea acostada, que va de lado a lado, está horizontal.","Una línea parada, que va de arriba abajo, está vertical.","Dos líneas que van juntas sin tocarse nunca están paralelas."],"ojo":"Horizontal y vertical no existen solas: se dicen siempre comparando con algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fae8527e-b6c6-5e83-837c-4a5ace0ecc90'::uuid, 'multiple_choice', 'Mira las dos líneas del dibujo. ¿Cómo están?', '{"options":["Van juntas y nunca se tocan","Se cruzan formando esquinas","Se juntan en una sola punta","Una está doblada y la otra no"],"correctIndex":0,"visual":{"tipo":"lineas","clase":"paralelas"},"ayuda":{"pista":"Compara la línea con el marco: mira si va como el suelo, como una pared, o cruzada.","pasos":["Una línea acostada, que va de lado a lado, está horizontal.","Una línea parada, que va de arriba abajo, está vertical.","Dos líneas que van juntas sin tocarse nunca están paralelas."],"ojo":"Horizontal y vertical no existen solas: se dicen siempre comparando con algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fae8527e-b6c6-5e83-837c-4a5ace0ecc90'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cómo se llaman estas dos líneas?', '{"options":["Perpendiculares","Paralelas","Horizontales","Verticales"],"correctIndex":0,"visual":{"tipo":"lineas","clase":"perpendiculares"},"ayuda":{"pista":"Mira si las líneas se cruzan o no, y cómo quedan las esquinas si se cruzan.","pasos":["Si por más que sigan nunca se tocan, son paralelas.","Si se cruzan dejando cuatro esquinas iguales, son perpendiculares.","Una sola línea no es ni lo uno ni lo otro: se dice si está horizontal o vertical."],"ojo":"Paralelas y perpendiculares hablan de DOS líneas; horizontal y vertical, de una sola."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fae8527e-b6c6-5e83-837c-4a5ace0ecc90'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cómo se llaman estas dos líneas?', '{"options":["Paralelas","Perpendiculares","Redondas","Torcidas"],"correctIndex":0,"visual":{"tipo":"lineas","clase":"paralelas"},"ayuda":{"pista":"Mira si las líneas se cruzan o no, y cómo quedan las esquinas si se cruzan.","pasos":["Si por más que sigan nunca se tocan, son paralelas.","Si se cruzan dejando cuatro esquinas iguales, son perpendiculares.","Una sola línea no es ni lo uno ni lo otro: se dice si está horizontal o vertical."],"ojo":"Paralelas y perpendiculares hablan de DOS líneas; horizontal y vertical, de una sola."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fae8527e-b6c6-5e83-837c-4a5ace0ecc90'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cómo se llama esta línea?', '{"options":["Vertical","Horizontal","Paralela","Redonda"],"correctIndex":0,"visual":{"tipo":"lineas","clase":"vertical"},"ayuda":{"pista":"Mira si las líneas se cruzan o no, y cómo quedan las esquinas si se cruzan.","pasos":["Si por más que sigan nunca se tocan, son paralelas.","Si se cruzan dejando cuatro esquinas iguales, son perpendiculares.","Una sola línea no es ni lo uno ni lo otro: se dice si está horizontal o vertical."],"ojo":"Paralelas y perpendiculares hablan de DOS líneas; horizontal y vertical, de una sola."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('757eebfc-8610-53e1-8309-d1393672499f'::uuid, 'multiple_choice', 'Dos líneas se cruzan y forman cuatro esquinas iguales.', '{"options":["Son perpendiculares","Son paralelas","Son horizontales","Son verticales"],"correctIndex":0,"ayuda":{"pista":"Lo que decide el nombre es si se cruzan y cómo quedan las esquinas.","pasos":["Pregúntate primero: ¿se llegan a tocar o no?","Si no se tocan nunca y van siempre a la misma distancia, son paralelas.","Si se cruzan y las cuatro esquinas quedan iguales, son perpendiculares."],"ojo":"Cruzarse no basta para ser perpendiculares: las esquinas tienen que quedar parejas."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('757eebfc-8610-53e1-8309-d1393672499f'::uuid, 'multiple_choice', 'Dos líneas van juntas y por más que sigan no se tocan.', '{"options":["Son paralelas","Son perpendiculares","Son horizontales","Son verticales"],"correctIndex":0,"ayuda":{"pista":"Lo que decide el nombre es si se cruzan y cómo quedan las esquinas.","pasos":["Pregúntate primero: ¿se llegan a tocar o no?","Si no se tocan nunca y van siempre a la misma distancia, son paralelas.","Si se cruzan y las cuatro esquinas quedan iguales, son perpendiculares."],"ojo":"Cruzarse no basta para ser perpendiculares: las esquinas tienen que quedar parejas."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('757eebfc-8610-53e1-8309-d1393672499f'::uuid, 'multiple_choice', 'Dos líneas se cruzan, pero las esquinas quedan disparejas.', '{"options":["Se cruzan, pero quedan torcidas","Se cruzan formando esquinas iguales","No se cruzan en ningún punto","Van siempre a la misma distancia"],"correctIndex":0,"ayuda":{"pista":"Lo que decide el nombre es si se cruzan y cómo quedan las esquinas.","pasos":["Pregúntate primero: ¿se llegan a tocar o no?","Si no se tocan nunca y van siempre a la misma distancia, son paralelas.","Si se cruzan y las cuatro esquinas quedan iguales, son perpendiculares."],"ojo":"Cruzarse no basta para ser perpendiculares: las esquinas tienen que quedar parejas."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', 'En un marco cuadrado, ¿cómo son el lado de arriba y el de abajo?', '{"options":["Paralelos entre ellos","Perpendiculares entre ellos","Una sola línea","Líneas torcidas"],"correctIndex":0,"ayuda":{"pista":"Piensa si esos dos lados llegarían a tocarse si los estiraras mucho.","pasos":["Los lados de enfrente van uno frente al otro y nunca se tocan: son paralelos.","Los lados que comparten una esquina se cruzan ahí mismo: son perpendiculares.","Mira en el marco cuáles te están nombrando antes de decidir."],"ojo":"En un marco hay las dos cosas a la vez: depende de qué par de lados mires."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', 'En un marco cuadrado, ¿cómo son un lado y el de al lado?', '{"options":["Perpendiculares entre ellos","Paralelos entre ellos","Una sola línea","Líneas torcidas"],"correctIndex":0,"ayuda":{"pista":"Piensa si esos dos lados llegarían a tocarse si los estiraras mucho.","pasos":["Los lados de enfrente van uno frente al otro y nunca se tocan: son paralelos.","Los lados que comparten una esquina se cruzan ahí mismo: son perpendiculares.","Mira en el marco cuáles te están nombrando antes de decidir."],"ojo":"En un marco hay las dos cosas a la vez: depende de qué par de lados mires."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', 'En una escalera, ¿cómo están los escalones entre sí?', '{"options":["Paralelos entre ellos","Perpendiculares entre ellos","Una sola línea","Líneas torcidas"],"correctIndex":0,"ayuda":{"pista":"Piensa si esos dos lados llegarían a tocarse si los estiraras mucho.","pasos":["Los lados de enfrente van uno frente al otro y nunca se tocan: son paralelos.","Los lados que comparten una esquina se cruzan ahí mismo: son perpendiculares.","Mira en el marco cuáles te están nombrando antes de decidir."],"ojo":"En un marco hay las dos cosas a la vez: depende de qué par de lados mires."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', '¿Cuál de estas cosas está casi siempre vertical?', '{"options":["Un poste de la luz","El piso del salón","La superficie del agua","El techo de la casa"],"correctIndex":0,"ayuda":{"pista":"Piensa cómo se ve esa cosa en la vida real: parada, acostada, o cruzando a otra.","pasos":["Lo que va de arriba abajo, como un poste o una pared, está vertical.","Lo que se extiende de lado a lado, como el piso o el agua quieta, está horizontal.","Dos cosas son perpendiculares cuando una está parada sobre la otra."],"ojo":"El agua quieta siempre queda horizontal: por eso sirve para saber si algo está derecho."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', '¿Cuál de estas cosas está casi siempre horizontal?', '{"options":["La superficie del agua","Un poste de la luz","Un árbol crecido","La pared del salón"],"correctIndex":0,"ayuda":{"pista":"Piensa cómo se ve esa cosa en la vida real: parada, acostada, o cruzando a otra.","pasos":["Lo que va de arriba abajo, como un poste o una pared, está vertical.","Lo que se extiende de lado a lado, como el piso o el agua quieta, está horizontal.","Dos cosas son perpendiculares cuando una está parada sobre la otra."],"ojo":"El agua quieta siempre queda horizontal: por eso sirve para saber si algo está derecho."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', '¿Cuál de estas parejas es perpendicular?', '{"options":["La pared y el piso","El piso y el techo","Dos postes de la luz","Dos rieles del tren"],"correctIndex":0,"ayuda":{"pista":"Piensa cómo se ve esa cosa en la vida real: parada, acostada, o cruzando a otra.","pasos":["Lo que va de arriba abajo, como un poste o una pared, está vertical.","Lo que se extiende de lado a lado, como el piso o el agua quieta, está horizontal.","Dos cosas son perpendiculares cuando una está parada sobre la otra."],"ojo":"El agua quieta siempre queda horizontal: por eso sirve para saber si algo está derecho."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', 'Los rieles del tren no se tocan nunca. ¿Cómo son?', '{"options":["Paralelos","Perpendiculares","Torcidos","Redondos"],"correctIndex":0,"ayuda":{"pista":"Si van juntas a la misma distancia, son una cosa; si se cruzan derechito, son otra.","pasos":["Van a la misma distancia y no se tocan nunca: paralelas.","Se cruzan dejando esquinas iguales: perpendiculares.","Busca en el enunciado cuál de las dos cosas está describiendo."],"ojo":"Que dos líneas no se toquen EN EL DIBUJO no basta: hay que pensar si se tocarían al seguir."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', 'El palo de una cruz atraviesa al otro derechito. ¿Cómo son?', '{"options":["Perpendiculares","Paralelos","Torcidos","Redondos"],"correctIndex":0,"ayuda":{"pista":"Si van juntas a la misma distancia, son una cosa; si se cruzan derechito, son otra.","pasos":["Van a la misma distancia y no se tocan nunca: paralelas.","Se cruzan dejando esquinas iguales: perpendiculares.","Busca en el enunciado cuál de las dos cosas está describiendo."],"ojo":"Que dos líneas no se toquen EN EL DIBUJO no basta: hay que pensar si se tocarían al seguir."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('bffe46f2-b47e-5c81-8f4a-a6c0b6702548'::uuid, 'multiple_choice', 'Los lados de una hoja de cuaderno, los de arriba y abajo:', '{"options":["Paralelos","Perpendiculares","Torcidos","Redondos"],"correctIndex":0,"ayuda":{"pista":"Si van juntas a la misma distancia, son una cosa; si se cruzan derechito, son otra.","pasos":["Van a la misma distancia y no se tocan nunca: paralelas.","Se cruzan dejando esquinas iguales: perpendiculares.","Busca en el enunciado cuál de las dos cosas está describiendo."],"ojo":"Que dos líneas no se toquen EN EL DIBUJO no basta: hay que pensar si se tocarían al seguir."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Caminas por una calle y doblas en la esquina. ¿Qué hiciste?', '{"options":["Cambié a la calle perpendicular","Seguí por la calle paralela","Me devolví por la misma calle","Crucé la calle sin doblar"],"correctIndex":0,"ayuda":{"pista":"Doblar en una esquina es pasarse a la calle que cruza; seguir derecho es quedarse en la misma.","pasos":["Si doblaste, cambiaste a una calle que cruza a la primera.","Si seguiste derecho, sigues en la misma calle.","Pasar a otra calle que va en la misma dirección es pasar a una paralela."],"ojo":"Cambiar de calle y devolverse no son lo mismo: devolverse es volver por donde viniste."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Caminas una calle y luego otra que va en la misma dirección.', '{"options":["Pasé a una calle paralela","Pasé a una calle perpendicular","Me devolví por la misma calle","Doblé en la esquina"],"correctIndex":0,"ayuda":{"pista":"Doblar en una esquina es pasarse a la calle que cruza; seguir derecho es quedarse en la misma.","pasos":["Si doblaste, cambiaste a una calle que cruza a la primera.","Si seguiste derecho, sigues en la misma calle.","Pasar a otra calle que va en la misma dirección es pasar a una paralela."],"ojo":"Cambiar de calle y devolverse no son lo mismo: devolverse es volver por donde viniste."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Para ir de la casa a la iglesia hay que doblar en dos esquinas.', '{"options":["Cambié de calle dos veces","Seguí siempre por la misma calle","Caminé siempre en línea recta","Volví al punto de partida"],"correctIndex":0,"ayuda":{"pista":"Doblar en una esquina es pasarse a la calle que cruza; seguir derecho es quedarse en la misma.","pasos":["Si doblaste, cambiaste a una calle que cruza a la primera.","Si seguiste derecho, sigues en la misma calle.","Pasar a otra calle que va en la misma dirección es pasar a una paralela."],"ojo":"Cambiar de calle y devolverse no son lo mismo: devolverse es volver por donde viniste."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Subes por las escaleras del edificio. ¿Cómo te mueves?', '{"options":["Hacia arriba, en vertical","Hacia el lado, en horizontal","Hacia atrás, devolviéndome","En redondo, dando vueltas"],"correctIndex":0,"ayuda":{"pista":"Piensa para dónde te lleva ese movimiento: arriba, abajo, o de lado.","pasos":["Subir o bajar es moverse en vertical.","Caminar por un pasillo plano es moverse en horizontal.","Dar vueltas alrededor de algo no es ni lo uno ni lo otro."],"ojo":"Un tobogán baja, pero no baja derecho: va bajando mientras avanza."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Caminas por el pasillo derecho del piso. ¿Cómo te mueves?', '{"options":["Hacia el lado, en horizontal","Hacia arriba, en vertical","Hacia abajo, en vertical","En redondo, dando vueltas"],"correctIndex":0,"ayuda":{"pista":"Piensa para dónde te lleva ese movimiento: arriba, abajo, o de lado.","pasos":["Subir o bajar es moverse en vertical.","Caminar por un pasillo plano es moverse en horizontal.","Dar vueltas alrededor de algo no es ni lo uno ni lo otro."],"ojo":"Un tobogán baja, pero no baja derecho: va bajando mientras avanza."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Bajas por el tobogán del parque. ¿Cómo te mueves?', '{"options":["Hacia abajo, en bajada","Hacia arriba, en vertical","Hacia el lado, en horizontal","En redondo, dando vueltas"],"correctIndex":0,"ayuda":{"pista":"Piensa para dónde te lleva ese movimiento: arriba, abajo, o de lado.","pasos":["Subir o bajar es moverse en vertical.","Caminar por un pasillo plano es moverse en horizontal.","Dar vueltas alrededor de algo no es ni lo uno ni lo otro."],"ojo":"Un tobogán baja, pero no baja derecho: va bajando mientras avanza."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Te dicen: «sigue derecho y no dobles». ¿Qué haces?', '{"options":["Camino en línea recta","Doblo en la primera esquina","Doblo en la segunda esquina","Me devuelvo por donde vine"],"correctIndex":0,"ayuda":{"pista":"Traduce la indicación a un movimiento: ¿te quedas en la misma calle o te cambias?","pasos":["«Sigue derecho» es quedarse en la misma calle, sin cambiar.","«Dobla» es cambiarse a la calle que cruza, y hay que saber para qué lado.","Si la indicación no dice para qué lado, falta un dato para poder seguirla."],"ojo":"Una indicación incompleta no es una indicación: hay que notar qué le falta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Te dicen: «dobla a la derecha en la esquina». ¿Qué haces?', '{"options":["Cambio a la calle de la derecha","Sigo derecho sin doblar","Cambio a la calle de la izquierda","Me devuelvo por donde vine"],"correctIndex":0,"ayuda":{"pista":"Traduce la indicación a un movimiento: ¿te quedas en la misma calle o te cambias?","pasos":["«Sigue derecho» es quedarse en la misma calle, sin cambiar.","«Dobla» es cambiarse a la calle que cruza, y hay que saber para qué lado.","Si la indicación no dice para qué lado, falta un dato para poder seguirla."],"ojo":"Una indicación incompleta no es una indicación: hay que notar qué le falta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('364b8aae-5d5e-5252-87e5-39fc060a3266'::uuid, 'multiple_choice', 'Te dicen: «la tienda queda enseguida». ¿Qué te falta saber?', '{"options":["Para qué lado queda","Cuánto cuestan las cosas","A qué hora abren","Quién atiende adentro"],"correctIndex":0,"ayuda":{"pista":"Traduce la indicación a un movimiento: ¿te quedas en la misma calle o te cambias?","pasos":["«Sigue derecho» es quedarse en la misma calle, sin cambiar.","«Dobla» es cambiarse a la calle que cruza, y hay que saber para qué lado.","Si la indicación no dice para qué lado, falta un dato para poder seguirla."],"ojo":"Una indicación incompleta no es una indicación: hay que notar qué le falta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('757eebfc-8610-53e1-8309-d1393672499f'::uuid, 'multiple_choice', '¿Por qué dos líneas paralelas nunca se cruzan?', '{"options":["Porque van siempre a igual distancia","Porque las dos están acostadas","Porque las dos están paradas","Porque las dos son muy cortas"],"correctIndex":0,"ayuda":{"pista":"La razón está en la distancia entre ellas: fíjate si esa distancia cambia o no.","pasos":["Dos paralelas van siempre separadas por lo mismo, de principio a fin.","Si la distancia nunca se achica, no hay manera de que lleguen a tocarse.","Las que se cruzan van en direcciones distintas, y por eso en algún punto se encuentran."],"ojo":"No es que sean cortas: aunque siguieran para siempre, tampoco se tocarían."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('757eebfc-8610-53e1-8309-d1393672499f'::uuid, 'multiple_choice', '¿Por qué dos líneas perpendiculares sí se cruzan?', '{"options":["Porque van en direcciones distintas","Porque van a la misma distancia","Porque las dos están acostadas","Porque las dos son muy largas"],"correctIndex":0,"ayuda":{"pista":"La razón está en la distancia entre ellas: fíjate si esa distancia cambia o no.","pasos":["Dos paralelas van siempre separadas por lo mismo, de principio a fin.","Si la distancia nunca se achica, no hay manera de que lleguen a tocarse.","Las que se cruzan van en direcciones distintas, y por eso en algún punto se encuentran."],"ojo":"No es que sean cortas: aunque siguieran para siempre, tampoco se tocarían."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('757eebfc-8610-53e1-8309-d1393672499f'::uuid, 'multiple_choice', '¿Puede una línea ser vertical y horizontal a la vez?', '{"options":["No, porque son direcciones distintas","Sí, si está doblada por la mitad","Sí, si es lo bastante larga","Depende de qué tan gruesa sea"],"correctIndex":0,"ayuda":{"pista":"La razón está en la distancia entre ellas: fíjate si esa distancia cambia o no.","pasos":["Dos paralelas van siempre separadas por lo mismo, de principio a fin.","Si la distancia nunca se achica, no hay manera de que lleguen a tocarse.","Las que se cruzan van en direcciones distintas, y por eso en algún punto se encuentran."],"ojo":"No es que sean cortas: aunque siguieran para siempre, tampoco se tocarían."}}'::jsonb, 10);
