insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Para devolverte en la cadena, ¿qué le haces a un «+5»?', '{"options":["Lo cambio por quitar 5","Lo dejo igual, sumando 5","Lo cambio por sumar 10","Lo cambio por quitar 10"],"correctIndex":0,"ayuda":{"pista":"Para deshacer un paso hay que hacer lo contrario de lo que decía.","pasos":["Lo contrario de sumar es restar, y lo contrario de restar es sumar.","El número no cambia: lo que cambia es la operación.","Y se empieza por el último paso, que es el que se deshace primero."],"ojo":"Deshacer no es repetir: si el paso sumaba, para volver hay que quitar."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Para devolverte en la cadena, ¿qué le haces a un «−4»?', '{"options":["Lo cambio por sumar 4","Lo dejo igual, quitando 4","Lo cambio por quitar 8","Lo cambio por sumar 8"],"correctIndex":0,"ayuda":{"pista":"Para deshacer un paso hay que hacer lo contrario de lo que decía.","pasos":["Lo contrario de sumar es restar, y lo contrario de restar es sumar.","El número no cambia: lo que cambia es la operación.","Y se empieza por el último paso, que es el que se deshace primero."],"ojo":"Deshacer no es repetir: si el paso sumaba, para volver hay que quitar."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Para devolverte en la cadena, ¿por dónde empiezas?', '{"options":["Por el último paso de todos","Por el primer paso de todos","Por el paso de la mitad","Por el que tenga el número mayor"],"correctIndex":0,"ayuda":{"pista":"Para deshacer un paso hay que hacer lo contrario de lo que decía.","pasos":["Lo contrario de sumar es restar, y lo contrario de restar es sumar.","El número no cambia: lo que cambia es la operación.","Y se empieza por el último paso, que es el que se deshace primero."],"ojo":"Deshacer no es repetir: si el paso sumaba, para volver hay que quitar."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Si a un número le sumas 7 y luego le quitas 7, ¿qué queda?', '{"options":["El mismo número del principio","El número más 14","El número menos 14","Siempre queda en cero"],"correctIndex":0,"ayuda":{"pista":"Dos operaciones contrarias con el mismo número se anulan entre ellas.","pasos":["Sumar y después quitar lo mismo deja el número como estaba.","Si los números no son iguales, no se anulan del todo: queda la diferencia.","Piensa qué sobró después de que se cancelara lo que se pudo cancelar."],"ojo":"Que se anulen no quiere decir que quede en cero: queda el número del principio."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Si a un número le quitas 5 y luego le sumas 5, ¿qué queda?', '{"options":["El mismo número del principio","El número más 10","El número menos 10","Siempre queda en cero"],"correctIndex":0,"ayuda":{"pista":"Dos operaciones contrarias con el mismo número se anulan entre ellas.","pasos":["Sumar y después quitar lo mismo deja el número como estaba.","Si los números no son iguales, no se anulan del todo: queda la diferencia.","Piensa qué sobró después de que se cancelara lo que se pudo cancelar."],"ojo":"Que se anulen no quiere decir que quede en cero: queda el número del principio."}}'::jsonb, 5);
