insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Sabes que 8 + 5 = 13. ¿Qué otra cuenta sabes ya?', '{"options":["Que 13 − 5 = 8","Que 13 + 5 = 8","Que 8 − 5 = 13","Que 5 − 8 = 13"],"correctIndex":0,"ayuda":{"pista":"De una suma que ya conoces salen restas gratis, sin volver a calcular.","pasos":["Si dos números juntos dan un total, quitarle uno al total devuelve el otro.","Del mismo modo, si una resta te da un resultado, sumarlo al que se fue devuelve el de partida.","Comprueba tu respuesta haciendo la cuenta al derecho."],"ojo":"El total nunca puede quedar de un lado de la resta como si fuera una parte."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Sabes que 14 − 6 = 8. ¿Qué otra cuenta sabes ya?', '{"options":["Que 8 + 6 = 14","Que 14 + 6 = 8","Que 6 + 14 = 8","Que 8 − 6 = 14"],"correctIndex":0,"ayuda":{"pista":"De una suma que ya conoces salen restas gratis, sin volver a calcular.","pasos":["Si dos números juntos dan un total, quitarle uno al total devuelve el otro.","Del mismo modo, si una resta te da un resultado, sumarlo al que se fue devuelve el de partida.","Comprueba tu respuesta haciendo la cuenta al derecho."],"ojo":"El total nunca puede quedar de un lado de la resta como si fuera una parte."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('01bce8eb-e882-532e-8392-879ad73bca96'::uuid, 'multiple_choice', 'Sabes que 9 + 7 = 16. ¿Qué otra cuenta sabes ya?', '{"options":["Que 16 − 9 = 7","Que 16 + 9 = 7","Que 9 − 7 = 16","Que 7 − 16 = 9"],"correctIndex":0,"ayuda":{"pista":"De una suma que ya conoces salen restas gratis, sin volver a calcular.","pasos":["Si dos números juntos dan un total, quitarle uno al total devuelve el otro.","Del mismo modo, si una resta te da un resultado, sumarlo al que se fue devuelve el de partida.","Comprueba tu respuesta haciendo la cuenta al derecho."],"ojo":"El total nunca puede quedar de un lado de la resta como si fuera una parte."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('099bb3d3-0a90-51ed-8397-a74d8eb0927e'::uuid, 'multiple_choice', 'Buscas un número probando. Probaste 5 y quedó corto.', '{"options":["Pruebo con uno más grande","Pruebo con uno más pequeño","Pruebo otra vez con el 5","Ya no se puede seguir probando"],"correctIndex":0,"ayuda":{"pista":"Cada intento te dice para qué lado moverte en el siguiente.","pasos":["Si el resultado quedó corto, el número que buscas es más grande.","Si se pasó, el que buscas es más pequeño.","Si quedó justo, ya lo encontraste y no hay que seguir probando."],"ojo":"Probar no es adivinar: cada intento descarta la mitad de las opciones que quedaban."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('099bb3d3-0a90-51ed-8397-a74d8eb0927e'::uuid, 'multiple_choice', 'Buscas un número probando. Probaste 9 y se pasó.', '{"options":["Pruebo con uno más pequeño","Pruebo con uno más grande","Pruebo otra vez con el 9","Ya no se puede seguir probando"],"correctIndex":0,"ayuda":{"pista":"Cada intento te dice para qué lado moverte en el siguiente.","pasos":["Si el resultado quedó corto, el número que buscas es más grande.","Si se pasó, el que buscas es más pequeño.","Si quedó justo, ya lo encontraste y no hay que seguir probando."],"ojo":"Probar no es adivinar: cada intento descarta la mitad de las opciones que quedaban."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('099bb3d3-0a90-51ed-8397-a74d8eb0927e'::uuid, 'multiple_choice', 'Buscas un número probando. Probaste 6 y quedó justo.', '{"options":["Ya lo encontré: es el 6","Pruebo con el 7, más grande","Pruebo con el 5, más pequeño","Tengo que probar los 10 números"],"correctIndex":0,"ayuda":{"pista":"Cada intento te dice para qué lado moverte en el siguiente.","pasos":["Si el resultado quedó corto, el número que buscas es más grande.","Si se pasó, el que buscas es más pequeño.","Si quedó justo, ya lo encontraste y no hay que seguir probando."],"ojo":"Probar no es adivinar: cada intento descarta la mitad de las opciones que quedaban."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select 'e2883077-04c4-53be-8bf0-33a76a6fb110'::uuid, d.id, 1, 'Utiliza las propiedades de las operaciones para encontrar números desconocidos en igualdades numéricas.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 9;
