insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('97a8abe1-a216-5745-8745-38444c8eb552'::uuid, 'multiple_choice', '¿Cuál signo va en el espacio? 9 ? 4 = 13', '{"options":["El de sumar","El de restar","El de multiplicar","El de repartir"],"correctIndex":0,"ayuda":{"pista":"Mira si el resultado es más grande o más pequeño que los números de partida.","pasos":["Si el resultado es mayor que los dos, se sumó o se multiplicó.","Si es menor, se restó o se repartió.","Después prueba la operación que pensaste y comprueba que dé exactamente."],"ojo":"No basta con que el resultado quede del lado correcto: tiene que dar el número exacto."}}'::jsonb, 2);
