insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('724d5350-9565-5d4d-83ce-16eb563ca596'::uuid, 'multiple_choice', '¿Cuál de estas cuentas NO da 12?', '{"options":["7 + 4","8 + 4","6 + 6","20 − 8"],"correctIndex":0,"ayuda":{"pista":"Ojo con el NO: hay que buscar la que falla, no la que cumple.","pasos":["Resuelve las cuentas una por una.","Ve marcando cuáles dan el número que dice el enunciado.","La que sobra, la que da distinto, es la respuesta."],"ojo":"En las preguntas con NO, la primera que te dé bien es justo la que NO sirve."}}'::jsonb, 4);
