insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e2883077-04c4-53be-8bf0-33a76a6fb110'::uuid, 'multiple_choice', '¿Cuál número va en el espacio? 15, 20, ?, 30', '{"options":["25","22","26","35"],"correctIndex":0,"ayuda":{"pista":"Averigua de cuánto en cuánto salta la serie usando dos números que sí estén.","pasos":["Busca dos números seguidos que estén completos y mira cuánto hay entre ellos.","Ese salto se repite en toda la serie, también donde está el hueco.","Aplícale el salto al número de antes del hueco y comprueba con el de después."],"ojo":"Comprobar por los dos lados es lo que te dice si acertaste con el salto."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e2883077-04c4-53be-8bf0-33a76a6fb110'::uuid, 'multiple_choice', '¿Cuál número va en el espacio? 8, ?, 16, 20', '{"options":["12","10","14","18"],"correctIndex":0,"ayuda":{"pista":"Averigua de cuánto en cuánto salta la serie usando dos números que sí estén.","pasos":["Busca dos números seguidos que estén completos y mira cuánto hay entre ellos.","Ese salto se repite en toda la serie, también donde está el hueco.","Aplícale el salto al número de antes del hueco y comprueba con el de después."],"ojo":"Comprobar por los dos lados es lo que te dice si acertaste con el salto."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e2883077-04c4-53be-8bf0-33a76a6fb110'::uuid, 'multiple_choice', '¿Cuál número va en el espacio? 40, 36, ?, 28', '{"options":["32","34","30","24"],"correctIndex":0,"ayuda":{"pista":"Averigua de cuánto en cuánto salta la serie usando dos números que sí estén.","pasos":["Busca dos números seguidos que estén completos y mira cuánto hay entre ellos.","Ese salto se repite en toda la serie, también donde está el hueco.","Aplícale el salto al número de antes del hueco y comprueba con el de después."],"ojo":"Comprobar por los dos lados es lo que te dice si acertaste con el salto."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('97a8abe1-a216-5745-8745-38444c8eb552'::uuid, 'multiple_choice', '¿Cuál signo va en el espacio? 20 ? 5 = 4', '{"options":["El de repartir","El de sumar","El de restar","El de multiplicar"],"correctIndex":0,"ayuda":{"pista":"Compara el tamaño del resultado con el de los números de partida.","pasos":["Un resultado mucho más pequeño suele venir de repartir.","Un resultado mucho más grande suele venir de multiplicar.","Prueba el signo que pensaste antes de responder."],"ojo":"Sumar y multiplicar los dos agrandan, pero no dan lo mismo: hay que probar."}}'::jsonb, 6);
