insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('724d5350-9565-5d4d-83ce-16eb563ca596'::uuid, 'multiple_choice', 'El 12 se puede escribir de varias formas. ¿Cuál sirve?', '{"options":["4 × 3","4 × 4","5 × 3","6 × 3"],"correctIndex":0,"ayuda":{"pista":"Un mismo número se puede escribir de muchas maneras; hay que probar cuál da ese número.","pasos":["Resuelve cada opción y mira qué número te da.","La que dé exactamente el número del enunciado es la que sirve.","Puede haber varias formas de escribirlo, pero aquí solo una está en la lista."],"ojo":"Que dos cuentas se parezcan no quiere decir que den lo mismo: hay que resolverlas."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('724d5350-9565-5d4d-83ce-16eb563ca596'::uuid, 'multiple_choice', 'El 18 se puede escribir de varias formas. ¿Cuál sirve?', '{"options":["6 × 3","6 × 4","5 × 3","4 × 3"],"correctIndex":0,"ayuda":{"pista":"Un mismo número se puede escribir de muchas maneras; hay que probar cuál da ese número.","pasos":["Resuelve cada opción y mira qué número te da.","La que dé exactamente el número del enunciado es la que sirve.","Puede haber varias formas de escribirlo, pero aquí solo una está en la lista."],"ojo":"Que dos cuentas se parezcan no quiere decir que den lo mismo: hay que resolverlas."}}'::jsonb, 7);
