insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('97a8abe1-a216-5745-8745-38444c8eb552'::uuid, 'multiple_choice', 'Empezaste en 30 y llegaste a 42. ¿Qué pasó en el camino?', '{"options":["Le sumaron 12","Le restaron 12","Lo repartieron en 12","Lo multiplicaron por 12"],"correctIndex":0,"ayuda":{"pista":"Compara el de llegada con el de partida: mira si creció o se achicó, y cuánto.","pasos":["Si el número creció, le sumaron o lo multiplicaron.","Si se achicó, le restaron o lo repartieron.","Mira la diferencia exacta y prueba con qué operación se consigue."],"ojo":"Crecer no siempre es sumar: multiplicar también crece, y mucho más rápido."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('97a8abe1-a216-5745-8745-38444c8eb552'::uuid, 'multiple_choice', 'Empezaste en 30 y llegaste a 18. ¿Qué pasó en el camino?', '{"options":["Le restaron 12","Le sumaron 12","Lo repartieron en 12","Lo multiplicaron por 12"],"correctIndex":0,"ayuda":{"pista":"Compara el de llegada con el de partida: mira si creció o se achicó, y cuánto.","pasos":["Si el número creció, le sumaron o lo multiplicaron.","Si se achicó, le restaron o lo repartieron.","Mira la diferencia exacta y prueba con qué operación se consigue."],"ojo":"Crecer no siempre es sumar: multiplicar también crece, y mucho más rápido."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('97a8abe1-a216-5745-8745-38444c8eb552'::uuid, 'multiple_choice', 'Empezaste en 6 y llegaste a 24. ¿Qué pasó en el camino?', '{"options":["Lo multiplicaron por 4","Le sumaron 4","Le restaron 4","Lo repartieron en 4"],"correctIndex":0,"ayuda":{"pista":"Compara el de llegada con el de partida: mira si creció o se achicó, y cuánto.","pasos":["Si el número creció, le sumaron o lo multiplicaron.","Si se achicó, le restaron o lo repartieron.","Mira la diferencia exacta y prueba con qué operación se consigue."],"ojo":"Crecer no siempre es sumar: multiplicar también crece, y mucho más rápido."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e8d26d79-66b3-53cc-83da-5690393177d5'::uuid, 'multiple_choice', 'Buscas dos números que sumen 9 y uno sea el doble del otro.', '{"options":["3 y 6","4 y 5","2 y 7","1 y 8"],"correctIndex":0,"ayuda":{"pista":"Prueba parejas que cumplan una condición y después comprueba la otra.","pasos":["Empieza por las parejas que sumen lo que pide el enunciado.","De esas, mira cuál cumple además la segunda condición.","Comprueba las dos cosas antes de responder, no solo una."],"ojo":"Una pareja que cumple una sola de las dos condiciones no sirve."}}'::jsonb, 9);
