insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e8d26d79-66b3-53cc-83da-5690393177d5'::uuid, 'multiple_choice', 'Buscas dos números que sumen 15 y uno sea el doble del otro.', '{"options":["5 y 10","6 y 9","7 y 8","4 y 11"],"correctIndex":0,"ayuda":{"pista":"Prueba parejas que cumplan una condición y después comprueba la otra.","pasos":["Empieza por las parejas que sumen lo que pide el enunciado.","De esas, mira cuál cumple además la segunda condición.","Comprueba las dos cosas antes de responder, no solo una."],"ojo":"Una pareja que cumple una sola de las dos condiciones no sirve."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('724d5350-9565-5d4d-83ce-16eb563ca596'::uuid, 'multiple_choice', '¿Cuántas parejas de números suman 3, contando el 0?', '{"options":["4","3","2","6"],"correctIndex":0,"ayuda":{"pista":"Ve armando las parejas en orden, empezando por el cero, y cuéntalas.","pasos":["Empieza por el cero y busca cuánto le falta para llegar al total.","Sigue con el uno, el dos, y así, hasta que empieces a repetir parejas al revés.","Cuenta cuántas te salieron."],"ojo":"Si cuentas por separado una pareja y la misma al revés, te da el doble de las que hay."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('724d5350-9565-5d4d-83ce-16eb563ca596'::uuid, 'multiple_choice', '¿Cuántas parejas de números suman 4, contando el 0?', '{"options":["5","4","3","8"],"correctIndex":0,"ayuda":{"pista":"Ve armando las parejas en orden, empezando por el cero, y cuéntalas.","pasos":["Empieza por el cero y busca cuánto le falta para llegar al total.","Sigue con el uno, el dos, y así, hasta que empieces a repetir parejas al revés.","Cuenta cuántas te salieron."],"ojo":"Si cuentas por separado una pareja y la misma al revés, te da el doble de las que hay."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('724d5350-9565-5d4d-83ce-16eb563ca596'::uuid, 'multiple_choice', '¿Cuántas parejas de números suman 5, contando el 0?', '{"options":["6","5","4","10"],"correctIndex":0,"ayuda":{"pista":"Ve armando las parejas en orden, empezando por el cero, y cuéntalas.","pasos":["Empieza por el cero y busca cuánto le falta para llegar al total.","Sigue con el uno, el dos, y así, hasta que empieces a repetir parejas al revés.","Cuenta cuántas te salieron."],"ojo":"Si cuentas por separado una pareja y la misma al revés, te da el doble de las que hay."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e8d26d79-66b3-53cc-83da-5690393177d5'::uuid, 'multiple_choice', 'De las parejas que suman 10, ¿cuál da el mayor al multiplicar?', '{"options":["5 y 5","1 y 9","2 y 8","3 y 7"],"correctIndex":0,"ayuda":{"pista":"Multiplica cada pareja y compara los resultados: ahí se ve el patrón.","pasos":["Toma cada pareja y multiplícala.","Anota los resultados y compáralos.","Vas a ver que el mayor sale cuando los dos números son lo más parecidos posible."],"ojo":"Todas las parejas suman lo mismo, así que la suma no ayuda a decidir: hay que multiplicar."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e8d26d79-66b3-53cc-83da-5690393177d5'::uuid, 'multiple_choice', 'De las parejas que suman 8, ¿cuál da el mayor al multiplicar?', '{"options":["4 y 4","1 y 7","2 y 6","3 y 5"],"correctIndex":0,"ayuda":{"pista":"Multiplica cada pareja y compara los resultados: ahí se ve el patrón.","pasos":["Toma cada pareja y multiplícala.","Anota los resultados y compáralos.","Vas a ver que el mayor sale cuando los dos números son lo más parecidos posible."],"ojo":"Todas las parejas suman lo mismo, así que la suma no ayuda a decidir: hay que multiplicar."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e8d26d79-66b3-53cc-83da-5690393177d5'::uuid, 'multiple_choice', 'De las parejas que suman 12, ¿cuál da el mayor al multiplicar?', '{"options":["6 y 6","2 y 10","3 y 9","4 y 8"],"correctIndex":0,"ayuda":{"pista":"Multiplica cada pareja y compara los resultados: ahí se ve el patrón.","pasos":["Toma cada pareja y multiplícala.","Anota los resultados y compáralos.","Vas a ver que el mayor sale cuando los dos números son lo más parecidos posible."],"ojo":"Todas las parejas suman lo mismo, así que la suma no ayuda a decidir: hay que multiplicar."}}'::jsonb, 11);
insert into learning_evidences (id, dba_id, num, texto) select 'fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, d.id, 1, 'Identifica la equivalencia de fichas u objetos con el valor de la variable.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 10;
insert into learning_evidences (id, dba_id, num, texto) select '02e8ff0f-7abc-5832-89b6-56bb903afed5'::uuid, d.id, 2, 'Organiza los datos en tablas de conteo y en pictogramas con escala (uno a muchos).' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 10;
insert into learning_evidences (id, dba_id, num, texto) select '767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, d.id, 3, 'Lee la información presentada en tablas de conteo, pictogramas con escala y gráficos de puntos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 10;
insert into learning_evidences (id, dba_id, num, texto) select 'afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, d.id, 4, 'Comunica los resultados respondiendo preguntas tales como: ¿cuántos hay en total?, ¿cuántos hay de cada dato?, ¿cuál es el dato que más se repite?, ¿cuál es el dato que menos se repite?' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 10;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'Cada dibujo vale 5 votos. ¿Cuánto valen 3 dibujos?', '{"options":["15 votos","8 votos","3 votos","5 votos"],"correctIndex":0,"ayuda":{"pista":"Cada dibujo vale varios: hay que repetir ese valor tantas veces como dibujos haya.","pasos":["Mira cuánto vale un solo dibujo.","Cuenta cuántos dibujos hay.","Suma el valor de uno tantas veces como dibujos tengas."],"ojo":"Sumar el valor con la cantidad de dibujos no da nada: hay que repetir, no juntar."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'Cada dibujo vale 10 votos. ¿Cuánto valen 4 dibujos?', '{"options":["40 votos","14 votos","4 votos","10 votos"],"correctIndex":0,"ayuda":{"pista":"Cada dibujo vale varios: hay que repetir ese valor tantas veces como dibujos haya.","pasos":["Mira cuánto vale un solo dibujo.","Cuenta cuántos dibujos hay.","Suma el valor de uno tantas veces como dibujos tengas."],"ojo":"Sumar el valor con la cantidad de dibujos no da nada: hay que repetir, no juntar."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'Cada dibujo vale 2 votos. ¿Cuánto valen 6 dibujos?', '{"options":["12 votos","8 votos","6 votos","2 votos"],"correctIndex":0,"ayuda":{"pista":"Cada dibujo vale varios: hay que repetir ese valor tantas veces como dibujos haya.","pasos":["Mira cuánto vale un solo dibujo.","Cuenta cuántos dibujos hay.","Suma el valor de uno tantas veces como dibujos tengas."],"ojo":"Sumar el valor con la cantidad de dibujos no da nada: hay que repetir, no juntar."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'Cada dibujo vale 5 votos y hay 20 votos. ¿Cuántos dibujos?', '{"options":["4 dibujos","15 dibujos","25 dibujos","20 dibujos"],"correctIndex":0,"ayuda":{"pista":"Aquí es al revés: sabes el total y buscas cuántos dibujos hacen falta.","pasos":["Pregúntate cuántas veces cabe el valor de un dibujo dentro del total.","Ve contando de ese valor en ese valor hasta llegar al total.","Las veces que contaste son los dibujos."],"ojo":"Restarle el valor de un dibujo al total no responde la pregunta: hay que repartir."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'Cada dibujo vale 10 votos y hay 50 votos. ¿Cuántos dibujos?', '{"options":["5 dibujos","40 dibujos","60 dibujos","50 dibujos"],"correctIndex":0,"ayuda":{"pista":"Aquí es al revés: sabes el total y buscas cuántos dibujos hacen falta.","pasos":["Pregúntate cuántas veces cabe el valor de un dibujo dentro del total.","Ve contando de ese valor en ese valor hasta llegar al total.","Las veces que contaste son los dibujos."],"ojo":"Restarle el valor de un dibujo al total no responde la pregunta: hay que repartir."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'Cada dibujo vale 2 votos y hay 14 votos. ¿Cuántos dibujos?', '{"options":["7 dibujos","12 dibujos","16 dibujos","14 dibujos"],"correctIndex":0,"ayuda":{"pista":"Aquí es al revés: sabes el total y buscas cuántos dibujos hacen falta.","pasos":["Pregúntate cuántas veces cabe el valor de un dibujo dentro del total.","Ve contando de ese valor en ese valor hasta llegar al total.","Las veces que contaste son los dibujos."],"ojo":"Restarle el valor de un dibujo al total no responde la pregunta: hay que repartir."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('02e8ff0f-7abc-5832-89b6-56bb903afed5'::uuid, 'multiple_choice', 'Con muchos datos, ¿por qué un dibujo vale varios y no uno?', '{"options":["Porque si no, no cabrían en la hoja","Porque así los datos se ven mayores","Porque así la cuenta da más fácil","Porque los dibujos salen más bonitos"],"correctIndex":0,"ayuda":{"pista":"Piensa qué pasaría con la hoja si cada dibujo valiera uno solo.","pasos":["Con muchos datos, dibujar uno por uno llenaría la hoja entera.","Por eso se agrupa: un dibujo representa varios.","Y entonces hay que escribir abajo cuánto vale cada uno, o nadie puede leerlo."],"ojo":"Si dos dibujos del mismo gráfico valen distinto, el gráfico engaña al que lo mira."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('02e8ff0f-7abc-5832-89b6-56bb903afed5'::uuid, 'multiple_choice', 'Si un dibujo vale 5 y otro vale 10 en el mismo gráfico:', '{"options":["El gráfico engaña al que lo lee","El gráfico queda más completo","El gráfico se lee más rápido","El gráfico no cambia en nada"],"correctIndex":0,"ayuda":{"pista":"Piensa qué pasaría con la hoja si cada dibujo valiera uno solo.","pasos":["Con muchos datos, dibujar uno por uno llenaría la hoja entera.","Por eso se agrupa: un dibujo representa varios.","Y entonces hay que escribir abajo cuánto vale cada uno, o nadie puede leerlo."],"ojo":"Si dos dibujos del mismo gráfico valen distinto, el gráfico engaña al que lo mira."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('02e8ff0f-7abc-5832-89b6-56bb903afed5'::uuid, 'multiple_choice', '¿Qué hay que escribir siempre debajo de un pictograma?', '{"options":["Cuánto vale cada dibujo","Cuántos dibujos hay en total","Quién hizo el pictograma","De qué color son los dibujos"],"correctIndex":0,"ayuda":{"pista":"Piensa qué pasaría con la hoja si cada dibujo valiera uno solo.","pasos":["Con muchos datos, dibujar uno por uno llenaría la hoja entera.","Por eso se agrupa: un dibujo representa varios.","Y entonces hay que escribir abajo cuánto vale cada uno, o nadie puede leerlo."],"ojo":"Si dos dibujos del mismo gráfico valen distinto, el gráfico engaña al que lo mira."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 5 votos. ¿Cuántos votos sacó el candidato 2?', '{"options":["45","55","50","44"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Cand 1","valor":20},{"etiqueta":"Cand 2","valor":45},{"etiqueta":"Cand 3","valor":25}]},"ayuda":{"pista":"Cuenta los dibujos de esa fila y después aplica lo que vale cada uno.","pasos":["Busca la fila que te preguntan y cuenta sus dibujos.","Mira debajo del gráfico cuánto vale cada dibujo.","Suma ese valor tantas veces como dibujos contaste."],"ojo":"Responder el número de dibujos en vez del número de votos es el error clásico."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 5 votos. ¿Cuántos votos sacó el candidato 3?', '{"options":["40","35","30","13"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Cand 1","valor":30},{"etiqueta":"Cand 2","valor":20},{"etiqueta":"Cand 3","valor":40}]},"ayuda":{"pista":"Cuenta los dibujos de esa fila y después aplica lo que vale cada uno.","pasos":["Busca la fila que te preguntan y cuenta sus dibujos.","Mira debajo del gráfico cuánto vale cada dibujo.","Suma ese valor tantas veces como dibujos contaste."],"ojo":"Responder el número de dibujos en vez del número de votos es el error clásico."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 10 libros. ¿Cuántos libros hay de ciencia?', '{"options":["60","70","80","16"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"📗","escala":10,"unidad":"libros","datos":[{"etiqueta":"Cuentos","valor":40},{"etiqueta":"Poesía","valor":20},{"etiqueta":"Ciencia","valor":60}]},"ayuda":{"pista":"Cuenta los dibujos de esa fila y después aplica lo que vale cada uno.","pasos":["Busca la fila que te preguntan y cuenta sus dibujos.","Mira debajo del gráfico cuánto vale cada dibujo.","Suma ese valor tantas veces como dibujos contaste."],"ojo":"Responder el número de dibujos en vez del número de votos es el error clásico."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 5 niños. ¿Qué día vinieron más niños?', '{"options":["El martes, que tuvo más","El lunes, que tuvo más","El miércoles, que tuvo más","Los tres días fueron iguales"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🧒","escala":5,"unidad":"niños","datos":[{"etiqueta":"Lunes","valor":20},{"etiqueta":"Martes","valor":35},{"etiqueta":"Miércoles","valor":15}]},"ayuda":{"pista":"Como todos los dibujos valen igual, gana la fila que tenga más dibujos.","pasos":["Compara cuántos dibujos tiene cada fila.","La fila con más dibujos es la del valor más alto, y la de menos, la más baja.","Si todas tienen los mismos dibujos, entonces quedaron iguales."],"ojo":"Aquí no hace falta calcular los totales: basta comparar, porque la escala es la misma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 5 niños. ¿Qué día vinieron menos niños?', '{"options":["El miércoles, que tuvo menos","El lunes, que tuvo menos","El martes, que tuvo menos","Los tres días fueron iguales"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🧒","escala":5,"unidad":"niños","datos":[{"etiqueta":"Lunes","valor":25},{"etiqueta":"Martes","valor":30},{"etiqueta":"Miércoles","valor":10}]},"ayuda":{"pista":"Como todos los dibujos valen igual, gana la fila que tenga más dibujos.","pasos":["Compara cuántos dibujos tiene cada fila.","La fila con más dibujos es la del valor más alto, y la de menos, la más baja.","Si todas tienen los mismos dibujos, entonces quedaron iguales."],"ojo":"Aquí no hace falta calcular los totales: basta comparar, porque la escala es la misma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 5 niños. ¿Qué día vinieron más niños?', '{"options":["Los tres días fueron iguales","El lunes, que tuvo más","El martes, que tuvo más","El miércoles, que tuvo más"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🧒","escala":5,"unidad":"niños","datos":[{"etiqueta":"Lunes","valor":20},{"etiqueta":"Martes","valor":20},{"etiqueta":"Miércoles","valor":20}]},"ayuda":{"pista":"Como todos los dibujos valen igual, gana la fila que tenga más dibujos.","pasos":["Compara cuántos dibujos tiene cada fila.","La fila con más dibujos es la del valor más alto, y la de menos, la más baja.","Si todas tienen los mismos dibujos, entonces quedaron iguales."],"ojo":"Aquí no hace falta calcular los totales: basta comparar, porque la escala es la misma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 5 votos. ¿Cuántos votos hay en total?', '{"options":["45","40","35","14"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":15},{"etiqueta":"Beto","valor":10},{"etiqueta":"Caro","valor":20}]},"ayuda":{"pista":"Calcula lo de cada fila y después júntalo todo.","pasos":["Convierte los dibujos de cada fila a su valor.","Suma los valores de todas las filas.","También puedes contar todos los dibujos del gráfico y aplicar la escala una sola vez."],"ojo":"No olvides ninguna fila: la más corta también suma."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 10 votos. ¿Cuántos votos hay en total?', '{"options":["60","70","80","16"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":10,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":20},{"etiqueta":"Beto","valor":30},{"etiqueta":"Caro","valor":10}]},"ayuda":{"pista":"Calcula lo de cada fila y después júntalo todo.","pasos":["Convierte los dibujos de cada fila a su valor.","Suma los valores de todas las filas.","También puedes contar todos los dibujos del gráfico y aplicar la escala una sola vez."],"ojo":"No olvides ninguna fila: la más corta también suma."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('767eb96e-ef9b-5429-897e-2d281095e1c3'::uuid, 'multiple_choice', 'Un dibujo vale 5 votos. ¿Cuántos votos hay en total?', '{"options":["45","55","50","44"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":25},{"etiqueta":"Beto","valor":5},{"etiqueta":"Caro","valor":15}]},"ayuda":{"pista":"Calcula lo de cada fila y después júntalo todo.","pasos":["Convierte los dibujos de cada fila a su valor.","Suma los valores de todas las filas.","También puedes contar todos los dibujos del gráfico y aplicar la escala una sola vez."],"ojo":"No olvides ninguna fila: la más corta también suma."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'El informe dice que ganó Beto. Mira el dibujo: ¿es cierto?', '{"options":["No: la que ganó fue Ana","Sí: Beto fue el que ganó","No: el que ganó fue Caro","No se puede saber quién ganó"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":30},{"etiqueta":"Beto","valor":20},{"etiqueta":"Caro","valor":15}]},"ayuda":{"pista":"Comprueba la afirmación contra el dibujo: no la creas solo porque está escrita.","pasos":["Lee con cuidado qué afirma exactamente el informe.","Busca en el gráfico los datos que hacen falta para comprobarlo.","Compara lo que dice con lo que muestra, y decide si coincide."],"ojo":"Que algo esté escrito en un informe no lo vuelve cierto: el gráfico es el que manda."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'El informe dice que ganó Ana. Mira el dibujo: ¿es cierto?', '{"options":["Sí: Ana fue la que ganó","No: el que ganó fue Beto","No: el que ganó fue Caro","No se puede saber quién ganó"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":35},{"etiqueta":"Beto","valor":25},{"etiqueta":"Caro","valor":10}]},"ayuda":{"pista":"Comprueba la afirmación contra el dibujo: no la creas solo porque está escrita.","pasos":["Lee con cuidado qué afirma exactamente el informe.","Busca en el gráfico los datos que hacen falta para comprobarlo.","Compara lo que dice con lo que muestra, y decide si coincide."],"ojo":"Que algo esté escrito en un informe no lo vuelve cierto: el gráfico es el que manda."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'El informe dice que Caro sacó el doble que Beto. ¿Es cierto?', '{"options":["Sí: Caro sacó el doble que Beto","No: Caro sacó menos que Beto","No: Caro sacó el triple que Beto","No se puede saber con el dibujo"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":15},{"etiqueta":"Beto","valor":10},{"etiqueta":"Caro","valor":20}]},"ayuda":{"pista":"Comprueba la afirmación contra el dibujo: no la creas solo porque está escrita.","pasos":["Lee con cuidado qué afirma exactamente el informe.","Busca en el gráfico los datos que hacen falta para comprobarlo.","Compara lo que dice con lo que muestra, y decide si coincide."],"ojo":"Que algo esté escrito en un informe no lo vuelve cierto: el gráfico es el que manda."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cuántos votos separan a Ana de Caro?', '{"options":["15","61","16","18"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":30},{"etiqueta":"Beto","valor":20},{"etiqueta":"Caro","valor":15}]},"ayuda":{"pista":"Calcula el valor de cada uno de los dos y réstalos.","pasos":["Cuenta los dibujos de cada una de las dos filas que te nombran.","Convierte cada fila a votos con la escala.","Réstale al mayor el menor."],"ojo":"Restar los DIBUJOS y no convertir a votos deja el resultado mucho más pequeño de lo real."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cuántos votos separan a Ana de Beto?', '{"options":["25","55","27","23"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":40},{"etiqueta":"Beto","valor":15},{"etiqueta":"Caro","valor":25}]},"ayuda":{"pista":"Calcula el valor de cada uno de los dos y réstalos.","pasos":["Cuenta los dibujos de cada una de las dos filas que te nombran.","Convierte cada fila a votos con la escala.","Réstale al mayor el menor."],"ojo":"Restar los DIBUJOS y no convertir a votos deja el resultado mucho más pequeño de lo real."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'Mira el dibujo. ¿Cuántos votos separan a Beto de Caro?', '{"options":["10","9","12","14"],"correctIndex":0,"visual":{"tipo":"pictograma","icono":"🟦","escala":5,"unidad":"votos","datos":[{"etiqueta":"Ana","valor":10},{"etiqueta":"Beto","valor":35},{"etiqueta":"Caro","valor":25}]},"ayuda":{"pista":"Calcula el valor de cada uno de los dos y réstalos.","pasos":["Cuenta los dibujos de cada una de las dos filas que te nombran.","Convierte cada fila a votos con la escala.","Réstale al mayor el menor."],"ojo":"Restar los DIBUJOS y no convertir a votos deja el resultado mucho más pequeño de lo real."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('02e8ff0f-7abc-5832-89b6-56bb903afed5'::uuid, 'multiple_choice', 'Anotaste con palitos: IIII IIII II. ¿Cuántos son?', '{"options":["10","3","11","2"],"correctIndex":0,"ayuda":{"pista":"Los palitos se anotan en grupos: cuenta los grupos completos y súmale los sueltos.","pasos":["Cada grupo completo vale lo mismo; cuenta cuántos grupos hay.","Suma después los palitos sueltos que quedaron al final.","El total es lo de los grupos más lo suelto."],"ojo":"Contar los grupos y olvidar los sueltos deja la cuenta corta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('02e8ff0f-7abc-5832-89b6-56bb903afed5'::uuid, 'multiple_choice', 'Anotaste con palitos: IIII III. ¿Cuántos son?', '{"options":["7","2","8","4"],"correctIndex":0,"ayuda":{"pista":"Los palitos se anotan en grupos: cuenta los grupos completos y súmale los sueltos.","pasos":["Cada grupo completo vale lo mismo; cuenta cuántos grupos hay.","Suma después los palitos sueltos que quedaron al final.","El total es lo de los grupos más lo suelto."],"ojo":"Contar los grupos y olvidar los sueltos deja la cuenta corta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('02e8ff0f-7abc-5832-89b6-56bb903afed5'::uuid, 'multiple_choice', 'Anotaste con palitos: IIII IIII IIII. ¿Cuántos son?', '{"options":["12","3","13","4"],"correctIndex":0,"ayuda":{"pista":"Los palitos se anotan en grupos: cuenta los grupos completos y súmale los sueltos.","pasos":["Cada grupo completo vale lo mismo; cuenta cuántos grupos hay.","Suma después los palitos sueltos que quedaron al final.","El total es lo de los grupos más lo suelto."],"ojo":"Contar los grupos y olvidar los sueltos deja la cuenta corta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'En la tabla, el sabor de fresa tiene 8 palitos. ¿Qué significa?', '{"options":["Ocho niños escogieron fresa","Hay ocho sabores de fresa","La fresa vale ocho pesos","Quedan ocho helados de fresa"],"correctIndex":0,"ayuda":{"pista":"Cada palito es una respuesta de alguien: piensa qué se estaba preguntando.","pasos":["En una tabla de conteo, cada marca es una vez que apareció ese dato.","El dato que más marcas tiene es el que más se repitió.","Si dos tienen las mismas marcas, los escogió la misma cantidad de gente."],"ojo":"Los palitos cuentan respuestas, no pesos ni precios ni cantidades de producto."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'El dato que más se repite en la tabla es el chocolate.', '{"options":["Es el que más gente escogió","Es el que menos gente escogió","Es el que más caro cuesta","Es el que primero se acabó"],"correctIndex":0,"ayuda":{"pista":"Cada palito es una respuesta de alguien: piensa qué se estaba preguntando.","pasos":["En una tabla de conteo, cada marca es una vez que apareció ese dato.","El dato que más marcas tiene es el que más se repitió.","Si dos tienen las mismas marcas, los escogió la misma cantidad de gente."],"ojo":"Los palitos cuentan respuestas, no pesos ni precios ni cantidades de producto."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('afdace4d-c51e-5e31-8361-d3be6d5e8a12'::uuid, 'multiple_choice', 'Dos sabores quedaron con el mismo número de palitos.', '{"options":["Los escogió la misma cantidad","El primero tiene más votos","Los dos quedaron sin votos","La tabla quedó mal hecha"],"correctIndex":0,"ayuda":{"pista":"Cada palito es una respuesta de alguien: piensa qué se estaba preguntando.","pasos":["En una tabla de conteo, cada marca es una vez que apareció ese dato.","El dato que más marcas tiene es el que más se repitió.","Si dos tienen las mismas marcas, los escogió la misma cantidad de gente."],"ojo":"Los palitos cuentan respuestas, no pesos ni precios ni cantidades de producto."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'En un gráfico de puntos, cada punto vale un niño. ¿Y 6 puntos?', '{"options":["Seis niños","Un niño","Doce niños","Tres niños"],"correctIndex":0,"ayuda":{"pista":"En un gráfico de puntos cada punto vale uno: se cuenta y ya.","pasos":["Cuenta los puntos de la columna que te preguntan.","Como cada punto vale uno, ese número es la respuesta.","La columna con más puntos es la que llega más arriba."],"ojo":"Es distinto del pictograma: ahí un dibujo vale varios, aquí un punto vale uno."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'En un gráfico de puntos, cada punto vale un niño. ¿Y 9 puntos?', '{"options":["Nueve niños","Un niño","Dieciocho niños","Tres niños"],"correctIndex":0,"ayuda":{"pista":"En un gráfico de puntos cada punto vale uno: se cuenta y ya.","pasos":["Cuenta los puntos de la columna que te preguntan.","Como cada punto vale uno, ese número es la respuesta.","La columna con más puntos es la que llega más arriba."],"ojo":"Es distinto del pictograma: ahí un dibujo vale varios, aquí un punto vale uno."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('fc1f2e48-cdeb-5fea-82c6-bbde116ad428'::uuid, 'multiple_choice', 'En un gráfico de puntos, ¿qué columna tiene más puntos?', '{"options":["La que llega más arriba","La que queda más a la izquierda","La que queda más a la derecha","La que tiene el punto más grande"],"correctIndex":0,"ayuda":{"pista":"En un gráfico de puntos cada punto vale uno: se cuenta y ya.","pasos":["Cuenta los puntos de la columna que te preguntan.","Como cada punto vale uno, ese número es la respuesta.","La columna con más puntos es la que llega más arriba."],"ojo":"Es distinto del pictograma: ahí un dibujo vale varios, aquí un punto vale uno."}}'::jsonb, 11);
insert into learning_evidences (id, dba_id, num, texto) select '80487f5d-55be-54f3-8790-3ae349945084'::uuid, d.id, 1, 'Diferencia situaciones cotidianas cuyo resultado puede ser incierto de aquellas cuyo resultado es conocido o seguro.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 11;
insert into learning_evidences (id, dba_id, num, texto) select '43e80179-7b70-56a2-890c-32698252e9d6'::uuid, d.id, 2, 'Identifica resultados posibles o imposibles, según corresponda, en una situación cotidiana' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 11;
insert into learning_evidences (id, dba_id, num, texto) select '370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, d.id, 3, 'Predice la ocurrencia o no de eventos cotidianos basado en sus observaciones.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2 and d.num = 11;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'Mañana sale el sol por la mañana. ¿Cómo es eso?', '{"options":["Seguro","Imposible","Puede pasar o no","Nunca se ha visto"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si eso pasa siempre, si no puede pasar nunca, o si depende.","pasos":["Lo que pasa siempre, sin fallar, es seguro.","Lo que no puede pasar de ninguna manera es imposible.","Lo que unas veces pasa y otras no, puede pasar o no."],"ojo":"Que algo sea muy probable no lo vuelve seguro: seguro es que no falla nunca."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'Mañana llueve en la tarde. ¿Cómo es eso?', '{"options":["Puede pasar o no","Seguro","Imposible","Nunca se ha visto"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si eso pasa siempre, si no puede pasar nunca, o si depende.","pasos":["Lo que pasa siempre, sin fallar, es seguro.","Lo que no puede pasar de ninguna manera es imposible.","Lo que unas veces pasa y otras no, puede pasar o no."],"ojo":"Que algo sea muy probable no lo vuelve seguro: seguro es que no falla nunca."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'Mañana un perro habla en español. ¿Cómo es eso?', '{"options":["Imposible","Seguro","Puede pasar o no","Pasa todos los días"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si eso pasa siempre, si no puede pasar nunca, o si depende.","pasos":["Lo que pasa siempre, sin fallar, es seguro.","Lo que no puede pasar de ninguna manera es imposible.","Lo que unas veces pasa y otras no, puede pasar o no."],"ojo":"Que algo sea muy probable no lo vuelve seguro: seguro es que no falla nunca."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'Sacas una ficha de una bolsa con puras fichas rojas.', '{"options":["Sale roja seguro","Puede salir azul","Es imposible que salga","Sale azul seguro"],"correctIndex":0,"ayuda":{"pista":"Mira qué hay dentro de la bolsa antes de decidir qué puede salir.","pasos":["Si todas las fichas son del mismo color, ese color sale seguro.","Si hay de varios colores, puede salir cualquiera de los que hay.","Un color que no esté en la bolsa es imposible que salga."],"ojo":"Lo que no está adentro no puede salir, por mucho que uno lo quiera."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'Sacas una ficha de una bolsa con rojas y azules.', '{"options":["Puede salir de cualquiera","Sale roja seguro","Sale azul seguro","Es imposible que salga"],"correctIndex":0,"ayuda":{"pista":"Mira qué hay dentro de la bolsa antes de decidir qué puede salir.","pasos":["Si todas las fichas son del mismo color, ese color sale seguro.","Si hay de varios colores, puede salir cualquiera de los que hay.","Un color que no esté en la bolsa es imposible que salga."],"ojo":"Lo que no está adentro no puede salir, por mucho que uno lo quiera."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'Sacas una ficha verde de una bolsa sin fichas verdes.', '{"options":["Es imposible que salga","Sale verde seguro","Puede salir de cualquiera","Sale verde casi siempre"],"correctIndex":0,"ayuda":{"pista":"Mira qué hay dentro de la bolsa antes de decidir qué puede salir.","pasos":["Si todas las fichas son del mismo color, ese color sale seguro.","Si hay de varios colores, puede salir cualquiera de los que hay.","Un color que no esté en la bolsa es imposible que salga."],"ojo":"Lo que no está adentro no puede salir, por mucho que uno lo quiera."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'En un dado de seis caras sale un número menor que 7.', '{"options":["Pasa siempre","Pasa a veces","No pasa nunca","Pasa una vez de cada seis"],"correctIndex":0,"ayuda":{"pista":"Piensa qué números tiene el dado y cuáles cumplen lo que dice la frase.","pasos":["Un dado normal solo tiene los números del 1 al 6.","Si TODOS los números cumplen la frase, eso pasa siempre.","Si NINGUNO la cumple, no pasa nunca; si solo algunos, pasa a veces."],"ojo":"El dado no tiene ni 0 ni números mayores que 6: esos son imposibles."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'En un dado de seis caras sale el número 4.', '{"options":["Pasa a veces","Pasa siempre","No pasa nunca","Pasa cinco veces de seis"],"correctIndex":0,"ayuda":{"pista":"Piensa qué números tiene el dado y cuáles cumplen lo que dice la frase.","pasos":["Un dado normal solo tiene los números del 1 al 6.","Si TODOS los números cumplen la frase, eso pasa siempre.","Si NINGUNO la cumple, no pasa nunca; si solo algunos, pasa a veces."],"ojo":"El dado no tiene ni 0 ni números mayores que 6: esos son imposibles."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', 'En un dado de seis caras sale el número 9.', '{"options":["No pasa nunca","Pasa siempre","Pasa a veces","Pasa una vez de cada seis"],"correctIndex":0,"ayuda":{"pista":"Piensa qué números tiene el dado y cuáles cumplen lo que dice la frase.","pasos":["Un dado normal solo tiene los números del 1 al 6.","Si TODOS los números cumplen la frase, eso pasa siempre.","Si NINGUNO la cumple, no pasa nunca; si solo algunos, pasa a veces."],"ojo":"El dado no tiene ni 0 ni números mayores que 6: esos son imposibles."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'En la bolsa hay 5 rojas y 1 azul. ¿Qué es más probable?', '{"options":["Que salga una roja","Que salga la azul","Que las dos tengan igual opción","Que no pueda salir ninguna"],"correctIndex":0,"ayuda":{"pista":"Compara de cuál color hay más: de ese hay más opción de que salga.","pasos":["Cuenta cuántas hay de cada color.","El color del que haya más tiene más opción de salir.","Si hay la misma cantidad de los dos, los dos tienen la misma opción."],"ojo":"Más opción no es seguridad: la ficha de la que hay una sola también puede salir."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'En la bolsa hay 1 roja y 6 azules. ¿Qué es más probable?', '{"options":["Que salga una azul","Que salga la roja","Que las dos tengan igual opción","Que no pueda salir ninguna"],"correctIndex":0,"ayuda":{"pista":"Compara de cuál color hay más: de ese hay más opción de que salga.","pasos":["Cuenta cuántas hay de cada color.","El color del que haya más tiene más opción de salir.","Si hay la misma cantidad de los dos, los dos tienen la misma opción."],"ojo":"Más opción no es seguridad: la ficha de la que hay una sola también puede salir."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'En la bolsa hay 4 rojas y 4 azules. ¿Qué es más probable?', '{"options":["Que las dos tengan igual opción","Que salga una roja","Que salga una azul","Que no pueda salir ninguna"],"correctIndex":0,"ayuda":{"pista":"Compara de cuál color hay más: de ese hay más opción de que salga.","pasos":["Cuenta cuántas hay de cada color.","El color del que haya más tiene más opción de salir.","Si hay la misma cantidad de los dos, los dos tienen la misma opción."],"ojo":"Más opción no es seguridad: la ficha de la que hay una sola también puede salir."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'Sacas una ficha de la bolsa. ¿Qué resultado es imposible?', '{"options":["Que salga una ficha amarilla","Que salga una ficha roja","Que salga una ficha azul","Que salga cualquiera de las dos"],"correctIndex":0,"ayuda":{"pista":"Imposible es lo que no puede pasar de ninguna manera, no lo que pasa poco.","pasos":["Mira qué resultados existen de verdad en esa situación.","Un resultado que no está entre ellos es imposible.","Un resultado que existe pero es raro no es imposible: es poco probable."],"ojo":"Confundir «difícil» con «imposible» es el error que persigue esta pregunta."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'Tiras un dado. ¿Cuál de estos resultados es imposible?', '{"options":["Que salga un cero","Que salga un uno","Que salga un seis","Que salga un número par"],"correctIndex":0,"ayuda":{"pista":"Imposible es lo que no puede pasar de ninguna manera, no lo que pasa poco.","pasos":["Mira qué resultados existen de verdad en esa situación.","Un resultado que no está entre ellos es imposible.","Un resultado que existe pero es raro no es imposible: es poco probable."],"ojo":"Confundir «difícil» con «imposible» es el error que persigue esta pregunta."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'Giras una ruleta de tres colores. ¿Qué es imposible?', '{"options":["Que caiga en un cuarto color","Que caiga dos veces igual","Que caiga en el primer color","Que caiga en el último color"],"correctIndex":0,"ayuda":{"pista":"Imposible es lo que no puede pasar de ninguna manera, no lo que pasa poco.","pasos":["Mira qué resultados existen de verdad en esa situación.","Un resultado que no está entre ellos es imposible.","Un resultado que existe pero es raro no es imposible: es poco probable."],"ojo":"Confundir «difícil» con «imposible» es el error que persigue esta pregunta."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'Una moneda cayó cara cuatro veces seguidas. ¿Y ahora?', '{"options":["Puede caer cara o sello igual","Ahora tiene que caer sello","Ahora va a caer cara otra vez","Ya no puede volver a caer cara"],"correctIndex":0,"ayuda":{"pista":"Piensa si lo que pasó antes puede cambiar lo que va a pasar ahora.","pasos":["La moneda y el dado no guardan memoria de lo que salió antes.","Cada tiro empieza de nuevo, con las mismas opciones de siempre.","Por eso lo que salió antes no obliga a nada en el siguiente tiro."],"ojo":"Pensar que «ya le toca» al otro lado es el error más común con las monedas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', 'Un dado cayó en 6 tres veces seguidas. ¿Y ahora?', '{"options":["Puede caer en cualquiera de los 6","Ahora ya no puede caer en 6","Ahora tiene que caer en 1","Ahora va a caer en 6 otra vez"],"correctIndex":0,"ayuda":{"pista":"Piensa si lo que pasó antes puede cambiar lo que va a pasar ahora.","pasos":["La moneda y el dado no guardan memoria de lo que salió antes.","Cada tiro empieza de nuevo, con las mismas opciones de siempre.","Por eso lo que salió antes no obliga a nada en el siguiente tiro."],"ojo":"Pensar que «ya le toca» al otro lado es el error más común con las monedas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43e80179-7b70-56a2-890c-32698252e9d6'::uuid, 'multiple_choice', '¿La moneda se acuerda de lo que salió antes?', '{"options":["No: cada tiro empieza de nuevo","Sí: por eso va cambiando","Sí: por eso repite lo mismo","Solo se acuerda de dos tiros"],"correctIndex":0,"ayuda":{"pista":"Piensa si lo que pasó antes puede cambiar lo que va a pasar ahora.","pasos":["La moneda y el dado no guardan memoria de lo que salió antes.","Cada tiro empieza de nuevo, con las mismas opciones de siempre.","Por eso lo que salió antes no obliga a nada en el siguiente tiro."],"ojo":"Pensar que «ya le toca» al otro lado es el error más común con las monedas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'David dice que SIEMPRE ganará porque sabe lanzar aviones.', '{"options":["Falso: le ayuda, pero no asegura","Cierto: el que sabe gana siempre","Falso: saber lanzar no sirve","Cierto: nadie más sabe lanzar"],"correctIndex":0,"ayuda":{"pista":"Distingue entre tener más opción de ganar y tener la victoria asegurada.","pasos":["Saber hacer algo mejora las opciones: eso es cierto.","Pero mejorar las opciones no es lo mismo que no poder perder nunca.","Basta con imaginar una sola vez en que pierda para que el «siempre» sea falso."],"ojo":"Una sola excepción tumba un «siempre». Para lo demás se dice «es probable»."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'David ganó 4 de 5 veces. ¿Qué puedes decir de la sexta?', '{"options":["Que tiene buena opción de ganar","Que va a ganar con seguridad","Que le toca perder esta vez","Que no se puede decir nada"],"correctIndex":0,"ayuda":{"pista":"Distingue entre tener más opción de ganar y tener la victoria asegurada.","pasos":["Saber hacer algo mejora las opciones: eso es cierto.","Pero mejorar las opciones no es lo mismo que no poder perder nunca.","Basta con imaginar una sola vez en que pierda para que el «siempre» sea falso."],"ojo":"Una sola excepción tumba un «siempre». Para lo demás se dice «es probable»."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'Es la primera vez que todos lanzan aviones. ¿Quién gana?', '{"options":["No se puede saber todavía","Gana el más alto de todos","Gana el que lance de último","Gana el del avión más grande"],"correctIndex":0,"ayuda":{"pista":"Distingue entre tener más opción de ganar y tener la victoria asegurada.","pasos":["Saber hacer algo mejora las opciones: eso es cierto.","Pero mejorar las opciones no es lo mismo que no poder perder nunca.","Basta con imaginar una sola vez en que pierda para que el «siempre» sea falso."],"ojo":"Una sola excepción tumba un «siempre». Para lo demás se dice «es probable»."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'Lleva diez días lloviendo por la tarde. ¿Y mañana?', '{"options":["Es probable que llueva otra vez","Va a llover con seguridad","Seguro que no llueve mañana","No se puede pensar nada de eso"],"correctIndex":0,"ayuda":{"pista":"Lo que has observado sirve para esperar algo, no para asegurarlo.","pasos":["Mira qué ha pasado hasta ahora y cuántas veces.","Si ha pasado muchas veces, es probable que vuelva a pasar.","Pero sigue siendo probable, no seguro: pudo cambiar."],"ojo":"Predecir con lo observado está bien; decir que es seguro, no."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'El bus ha llegado tarde toda la semana. ¿Y mañana?', '{"options":["Puede volver a llegar tarde","Va a llegar tarde con seguridad","Seguro que mañana llega temprano","No se puede pensar nada de eso"],"correctIndex":0,"ayuda":{"pista":"Lo que has observado sirve para esperar algo, no para asegurarlo.","pasos":["Mira qué ha pasado hasta ahora y cuántas veces.","Si ha pasado muchas veces, es probable que vuelva a pasar.","Pero sigue siendo probable, no seguro: pudo cambiar."],"ojo":"Predecir con lo observado está bien; decir que es seguro, no."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'El equipo ganó una vez y perdió nueve. ¿Y el próximo?', '{"options":["Tiene poca opción de ganar","Va a ganar con seguridad","Va a perder con seguridad","Tiene la misma opción que antes"],"correctIndex":0,"ayuda":{"pista":"Lo que has observado sirve para esperar algo, no para asegurarlo.","pasos":["Mira qué ha pasado hasta ahora y cuántas veces.","Si ha pasado muchas veces, es probable que vuelva a pasar.","Pero sigue siendo probable, no seguro: pudo cambiar."],"ojo":"Predecir con lo observado está bien; decir que es seguro, no."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'Sacaste 20 fichas y 18 eran rojas. ¿Qué hay en la bolsa?', '{"options":["Casi todas las fichas son rojas","Casi todas las fichas son azules","Hay mitad rojas y mitad azules","No hay manera de imaginarlo"],"correctIndex":0,"ayuda":{"pista":"Lo que sacaste da una idea de lo que hay adentro, si sacaste suficientes.","pasos":["Mira cuántas sacaste en total y cómo se repartieron.","Si casi todas salieron de un color, lo más probable es que adentro haya sobre todo de ese.","Si salieron parejas, lo más probable es que adentro haya parecido de los dos."],"ojo":"Con muy pocas veces no se puede concluir nada: hacen falta varias."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'Sacaste 20 fichas: 10 rojas y 10 azules. ¿Qué hay en la bolsa?', '{"options":["Hay mitad rojas y mitad azules","Casi todas las fichas son rojas","Casi todas las fichas son azules","No hay manera de imaginarlo"],"correctIndex":0,"ayuda":{"pista":"Lo que sacaste da una idea de lo que hay adentro, si sacaste suficientes.","pasos":["Mira cuántas sacaste en total y cómo se repartieron.","Si casi todas salieron de un color, lo más probable es que adentro haya sobre todo de ese.","Si salieron parejas, lo más probable es que adentro haya parecido de los dos."],"ojo":"Con muy pocas veces no se puede concluir nada: hacen falta varias."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('370b4095-5f8c-5aaf-8d3a-47ad981ec779'::uuid, 'multiple_choice', 'Sacaste 2 fichas nada más y las dos eran rojas.', '{"options":["Son muy pocas fichas para decir","Todas las fichas deben ser rojas","Hay mitad rojas y mitad azules","Casi todas las fichas son azules"],"correctIndex":0,"ayuda":{"pista":"Lo que sacaste da una idea de lo que hay adentro, si sacaste suficientes.","pasos":["Mira cuántas sacaste en total y cómo se repartieron.","Si casi todas salieron de un color, lo más probable es que adentro haya sobre todo de ese.","Si salieron parejas, lo más probable es que adentro haya parecido de los dos."],"ojo":"Con muy pocas veces no se puede concluir nada: hacen falta varias."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', '¿Cuál de estas cosas ya se sabe antes de que pase?', '{"options":["Que el lunes sigue al domingo","Que mañana te encuentres a un amigo","Que te saques un diez en el examen","Que el bus venga lleno mañana"],"correctIndex":0,"ayuda":{"pista":"Separa lo que está decidido de antemano de lo que depende de cómo salgan las cosas.","pasos":["Lo que sigue una regla fija —los días, los meses— ya se sabe antes.","Lo que depende de la suerte o de otra gente no se sabe hasta que pasa.","Y lo que contradice una regla fija no va a pasar nunca."],"ojo":"Que algo sea muy probable no lo vuelve sabido: sabido es lo que no puede salir de otra forma."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', '¿Cuál de estas cosas no se sabe hasta que pase?', '{"options":["Que mañana te encuentres a un amigo","Que el lunes siga al domingo","Que el año tenga doce meses","Que febrero venga después de enero"],"correctIndex":0,"ayuda":{"pista":"Separa lo que está decidido de antemano de lo que depende de cómo salgan las cosas.","pasos":["Lo que sigue una regla fija —los días, los meses— ya se sabe antes.","Lo que depende de la suerte o de otra gente no se sabe hasta que pasa.","Y lo que contradice una regla fija no va a pasar nunca."],"ojo":"Que algo sea muy probable no lo vuelve sabido: sabido es lo que no puede salir de otra forma."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('80487f5d-55be-54f3-8790-3ae349945084'::uuid, 'multiple_choice', '¿Cuál de estas cosas no va a pasar nunca?', '{"options":["Que la semana tenga ocho días","Que llueva dos días seguidos","Que te encuentres a un amigo","Que el bus llegue tarde"],"correctIndex":0,"ayuda":{"pista":"Separa lo que está decidido de antemano de lo que depende de cómo salgan las cosas.","pasos":["Lo que sigue una regla fija —los días, los meses— ya se sabe antes.","Lo que depende de la suerte o de otra gente no se sabe hasta que pasa.","Y lo que contradice una regla fija no va a pasar nunca."],"ojo":"Que algo sea muy probable no lo vuelve sabido: sabido es lo que no puede salir de otra forma."}}'::jsonb, 10);
