-- Matemáticas, grado 2.
-- Los once DBA del MEN, con las evidencias literales del documento oficial.
-- Trae lo que el grado 1 no tenía: multiplicación y reparto, suma y resta en
-- columna hasta 999, pictogramas con escala, relojes de manecillas y las
-- cadenas numéricas del ejemplo del DBA 8.

do $$
declare v_subject uuid;
begin
  select id into v_subject from subjects where slug = 'matematicas';
  delete from exercises where evidence_id in (
    select le.id from learning_evidences le join dbas d on d.id = le.dba_id
    where d.subject_id = v_subject and d.grade = 2);
  delete from learning_evidences where dba_id in (
    select id from dbas where subject_id = v_subject and grade = 2);
end $$;

-- ===== DBA 1: 3 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 2: 2 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 3: 3 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 4: 4 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 5: 3 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 6: 3 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 7: 4 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 8: 2 evidencias · 10 ranuras · 30 ejercicios =====

-- ===== DBA 9: 4 evidencias · 11 ranuras · 33 ejercicios =====

-- ===== DBA 10: 4 evidencias · 11 ranuras · 33 ejercicios =====

-- ===== DBA 11: 3 evidencias · 10 ranuras · 30 ejercicios =====

do $$
declare n_ev int; n_ex int; n_malas int; n_ranuras int; n_mudos int;
begin
  select count(*) into n_ev from learning_evidences le join dbas d on d.id = le.dba_id
    join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 2;
  select count(*) into n_ex from exercises e join learning_evidences le on le.id = e.evidence_id
    join dbas d on d.id = le.dba_id join subjects s on s.id = d.subject_id and s.slug = 'matematicas'
    where d.grade = 2;
  select count(*) into n_malas from exercises e join learning_evidences le on le.id = e.evidence_id
    join dbas d on d.id = le.dba_id join subjects s on s.id = d.subject_id and s.slug = 'matematicas'
    where d.grade = 2 and (jsonb_array_length(e.config->'options') <> 4
      or (select count(distinct v) from jsonb_array_elements_text(e.config->'options') v) <> 4
      or length(e.prompt) > 70);
  -- Toda ranura de toda lección tiene que tener exactamente 3 versiones: es lo
  -- que sostiene que repetir no sea memorizar.
  select count(*) into n_ranuras from (
    select d.num, e.order_in_lesson from exercises e
      join learning_evidences le on le.id = e.evidence_id
      join dbas d on d.id = le.dba_id
      join subjects s on s.id = d.subject_id and s.slug = 'matematicas'
    where d.grade = 2 group by d.num, e.order_in_lesson having count(*) <> 3) t;
  -- Ningún ejercicio puede quedar mudo: o trae la ayuda escrita, o trae una
  -- operación de la cual la app deriva los pasos. Un ejercicio sin ninguna de
  -- las dos solo sabe decirle al niño que se equivocó.
  select count(*) into n_mudos from exercises e
    join learning_evidences le on le.id = e.evidence_id
    join dbas d on d.id = le.dba_id
    join subjects s on s.id = d.subject_id and s.slug = 'matematicas'
   where d.grade = 2
     and e.config->'ayuda' is null
     and e.config->'operation' is null
     and e.config->'ayudaOp' is null;
  if n_ev <> 35 then raise exception 'evidencias: % (esperadas 35)', n_ev; end if;
  if n_ex <> 336 then raise exception 'ejercicios: % (esperados 336)', n_ex; end if;
  if n_malas <> 0 then raise exception '% ejercicios mal formados', n_malas; end if;
  if n_ranuras <> 0 then raise exception '% ranuras que no tienen 3 versiones', n_ranuras; end if;
  if n_mudos <> 0 then raise exception '% ejercicios sin ayuda ni operación', n_mudos; end if;
end $$;
